import re
import os


def task_func(request):
    if not isinstance(request, str):
        return "HTTP/1.1 400 Bad Request\r\n\r\nBad Request"

    lines = request.splitlines()
    if not lines:
        return "HTTP/1.1 400 Bad Request\r\n\r\nBad Request"

    match = re.fullmatch(
        r"GET[ \t]+([^ \t\r\n]+)[ \t]+HTTP/\d+(?:\.\d+)?[ \t]*",
        lines[0],
    )
    if not match:
        return "HTTP/1.1 400 Bad Request\r\n\r\nBad Request"

    requested_path = match.group(1).split("?", 1)[0].lstrip("/")
    root_path = os.path.realpath(os.getcwd())
    file_path = os.path.realpath(os.path.join(root_path, requested_path))

    try:
        if os.path.commonpath((root_path, file_path)) != root_path:
            return "HTTP/1.1 404 Not Found\r\n\r\nFile Not Found"
    except ValueError:
        return "HTTP/1.1 404 Not Found\r\n\r\nFile Not Found"

    if not os.path.isfile(file_path):
        return "HTTP/1.1 404 Not Found\r\n\r\nFile Not Found"

    try:
        with open(file_path, "r", encoding="utf-8") as file:
            content = file.read()
    except (OSError, UnicodeDecodeError):
        return "HTTP/1.1 404 Not Found\r\n\r\nFile Not Found"

    return (
        "HTTP/1.1 200 OK\r\n"
        f"Content-Length: {len(content.encode('utf-8'))}\r\n"
        "\r\n"
        f"{content}"
    )

