import collections


def task_func(url, column_name, csv_file_path):
    try:
        urllib.request.urlretrieve(url, csv_file_path)
    except Exception:
        try:
            if os.path.exists(csv_file_path):
                os.remove(csv_file_path)
        except OSError:
            pass
        raise

    try:
        with open(csv_file_path, "r", encoding="utf-8", newline="") as csv_file:
            reader = csv.DictReader(csv_file)

            if not reader.fieldnames or column_name not in reader.fieldnames:
                raise ValueError(
                    f"The provided column_name '{column_name}' does not exist "
                    "in the CSV file."
                )

            return dict(collections.Counter(row[column_name] for row in reader))
    finally:
        try:
            if os.path.exists(csv_file_path):
                os.remove(csv_file_path)
        except OSError:
            pass

import pandas as pd
import seaborn as sns
import numpy as np
import ast


def task_func(csv_file):
    columns = ["email", "list", "sum", "mean", "std"]

    try:
        source_df = pd.read_csv(csv_file)
    except pd.errors.EmptyDataError:
        result_df = pd.DataFrame(columns=columns)
        return result_df, sns.histplot(x=result_df["mean"])

    required_columns = {"email", "list"}
    missing = required_columns - set(source_df.columns)
    if missing:
        raise ValueError(
            f"Missing required column(s): {', '.join(sorted(missing))}"
        )

    rows = []
    for index, row in source_df.iterrows():
        raw_values = row["list"]

        try:
            values = ast.literal_eval(raw_values) if isinstance(raw_values, str) else raw_values
        except (SyntaxError, ValueError) as exc:
            raise ValueError(
                f"Malformed list in row {index}: {raw_values!r}"
            ) from exc

        if not isinstance(values, list):
            raise ValueError(
                f"List value in row {index} must be a list, "
                f"got {type(values).__name__}"
            )

        if values:
            try:
                numeric_values = np.asarray(values, dtype=float)
            except (TypeError, ValueError) as exc:
                raise ValueError(
                    f"List in row {index} contains non-numeric values"
                ) from exc

            if not np.all(np.isfinite(numeric_values)):
                raise ValueError(
                    f"List in row {index} contains NaN or infinite values"
                )

            total = np.sum(numeric_values)
            mean = np.mean(numeric_values)
            std = np.std(numeric_values)
        else:
            total = mean = std = np.nan

        rows.append(
            {
                "email": row["email"],
                "list": values,
                "sum": total,
                "mean": mean,
                "std": std,
            }
        )

    result_df = pd.DataFrame(rows, columns=columns)
    ax = sns.histplot(x=result_df["mean"].dropna())
    return result_df, ax

