# Constants
MIN_PERCENTAGE = 0.75


def task_func(data, cols, percentage):
    if not isinstance(data, pd.DataFrame):
        raise TypeError("data must be a pandas DataFrame")

    if not isinstance(cols, (list, tuple)):
        raise TypeError("cols must be a list or tuple")

    if not isinstance(percentage, (int, float)) or isinstance(percentage, bool):
        raise TypeError("percentage must be numeric")

    if not 0 <= percentage <= 1:
        raise ValueError("percentage must be between 0 and 1")

    missing = [column for column in cols if column not in data.columns]
    if missing:
        raise ValueError(f"Columns not found in data: {missing}")

    if len(set(cols)) != len(cols):
        raise ValueError("cols must contain unique column names")

    correlations = data[list(cols)].corr()
    corr_combinations = []

    for column_a, column_b in combinations(cols, 2):
        correlation = correlations.loc[column_a, column_b]
        if pd.notna(correlation) and abs(correlation) > percentage:
            corr_combinations.append((column_a, column_b))

    return corr_combinations

import re
import os
import subprocess

def task_func(dir_path, exe_pattern, execute_files=True):
    pattern = re.compile(exe_pattern)
    matches = []

    with os.scandir(dir_path) as entries:
        for entry in entries:
            try:
                if (
                    entry.is_file()
                    and os.access(entry.path, os.X_OK)
                    and pattern.search(entry.name)
                ):
                    matches.append(entry.path)
            except OSError:
                continue

    matches.sort()

    if not execute_files:
        return matches

    results = []
    for path in matches:
        completed = subprocess.run(
            [path],
            capture_output=True,
            text=True,
            check=False,
        )
        results.append(completed.stdout)

    return results

