import pandas as pd
import matplotlib.pyplot as plt


def task_func(file_path):
    """Identify duplicate rows in a CSV file and plot their counts."""
    if hasattr(file_path, "__fspath__"):
        file_path = file_path.__fspath__()

    if isinstance(file_path, bytes):
        valid_extension = file_path.lower().endswith(b".csv")
    elif isinstance(file_path, str):
        valid_extension = file_path.lower().endswith(".csv")
    else:
        valid_extension = False

    if not valid_extension:
        raise ValueError("file_path must refer to a CSV file")

    rows = []

    try:
        with open(file_path, "r", encoding="utf-8", newline="") as csv_file:
            reader = csv.reader(csv_file, strict=True)
            expected_columns = None

            for row in reader:
                if expected_columns is None:
                    expected_columns = len(row)
                elif len(row) != expected_columns:
                    raise ValueError("CSV rows have inconsistent column counts")

                rows.append(tuple(row))
    except csv.Error as exc:
        raise ValueError("Invalid CSV format") from exc

    counts = Counter(rows)
    duplicate_counts = {
        row: count for row, count in counts.items() if count > 1
    }

    duplicate_df = pd.DataFrame(
        [
            {"row": str(row), "count": count}
            for row, count in duplicate_counts.items()
        ]
    )

    _, ax = plt.subplots()

    if not duplicate_df.empty:
        duplicate_df.plot(
            kind="bar",
            x="row",
            y="count",
            ax=ax,
            legend=False,
        )
        ax.set_xlabel("Duplicate row")
        ax.set_ylabel("Count")
        ax.tick_params(axis="x", rotation=45)
    else:
        ax.set_xlabel("Duplicate row")
        ax.set_ylabel("Count")

    ax.set_title("Duplicate CSV Rows")
    ax.figure.tight_layout()

    return duplicate_counts, ax

