import numpy as np
import pandas as pd
from sklearn.preprocessing import StandardScaler


def task_func(P, T):
    P = np.asarray(P)
    T = np.asarray(T)

    if P.ndim != 2:
        raise ValueError("P must be a 2D matrix.")

    if T.ndim != 3:
        raise ValueError("T must be a 3D tensor.")

    if P.shape[1] != T.shape[0]:
        raise ValueError(
            "Incompatible shapes: P's number of columns must equal "
            "T's first dimension."
        )

    result = P @ T.reshape(T.shape[0], -1)
    normalized_result = StandardScaler().fit_transform(result)

    columns = [
        f"feature_{index}" for index in range(normalized_result.shape[1])
    ]

    return pd.DataFrame(normalized_result, columns=columns)

