# Constants
CSV_FILE_PATH = 'scraped_data.csv'


def task_func(url):
    if not isinstance(url, str) or not url.strip():
        raise ValueError("url must be a non-empty string")

    parsed_url = urlparse(url)
    if parsed_url.scheme not in ("http", "https") or not parsed_url.netloc:
        raise ValueError(f"Invalid URL: {url}")

    with urllib.request.urlopen(url) as response:
        content = response.read()
        charset = "utf-8"

        response_headers = getattr(response, "headers", None)
        if response_headers is not None:
            get_charset = getattr(response_headers, "get_content_charset", None)
            if callable(get_charset):
                charset = get_charset() or charset

        try:
            content = content.decode(charset, errors="replace")
        except LookupError:
            content = content.decode("utf-8", errors="replace")

    soup = BeautifulSoup(content, "html.parser")
    tables = soup.find_all("table")
    rows = []

    if tables:
        table = tables[0]
        table_rows = table.find_all("tr")
        header_row = next(
            (row for row in table_rows if row.find_all("th")),
            None,
        )

        if header_row is not None:
            headers = [
                " ".join(cell.get_text(" ", strip=True).split())
                for cell in header_row.find_all(["th", "td"])
            ]
            data_rows = [row for row in table_rows if row is not header_row]
        else:
            max_columns = max(
                (len(row.find_all(["th", "td"])) for row in table_rows),
                default=1,
            )
            headers = [
                f"column_{index}"
                for index in range(1, max_columns + 1)
            ]
            data_rows = table_rows

        headers = [
            header or f"column_{index + 1}"
            for index, header in enumerate(headers)
        ]

        for row in data_rows:
            values = [
                " ".join(cell.get_text(" ", strip=True).split())
                for cell in row.find_all(["th", "td"])
            ]
            if any(values):
                values = (values + [""] * len(headers))[:len(headers)]
                rows.append(values)
    else:
        headers = ["text"]
        text = " ".join(soup.get_text(" ", strip=True).split())
        if text:
            rows.append([text])

    parent_directory = os.path.dirname(CSV_FILE_PATH)
    if parent_directory:
        os.makedirs(parent_directory, exist_ok=True)

    with open(CSV_FILE_PATH, "w", encoding="utf-8", newline="") as csv_file:
        writer = csv.writer(csv_file)
        writer.writerow(headers)
        writer.writerows(rows)

    return CSV_FILE_PATH

