import json
import csv
import os
import base64


def task_func(raw_string, filename, output_dir):
    if not isinstance(filename, str) or not filename:
        raise ValueError("filename must be a non-empty string")
    if not isinstance(output_dir, str) or not output_dir:
        raise ValueError("output_dir must be a non-empty string")

    data = json.loads(base64.b64decode(raw_string, validate=True).decode("utf-8"))

    os.makedirs(output_dir, exist_ok=True)
    file_path = os.path.join(output_dir, filename)

    with open(file_path, "w", newline="", encoding="utf-8") as csv_file:
        if isinstance(data, dict):
            fieldnames = list(data.keys())
            if fieldnames:
                writer = csv.DictWriter(csv_file, fieldnames=fieldnames)
                writer.writeheader()
                writer.writerow(data)
        elif isinstance(data, list) and all(isinstance(item, dict) for item in data):
            fieldnames = []
            for item in data:
                for key in item:
                    if key not in fieldnames:
                        fieldnames.append(key)

            if fieldnames:
                writer = csv.DictWriter(csv_file, fieldnames=fieldnames)
                writer.writeheader()
                writer.writerows(data)
        else:
            writer = csv.writer(csv_file)
            writer.writerow(["value"])
            writer.writerow([data])

    return file_path

import pandas as pd
import re
import random


def task_func(s: str, seed: int = 0) -> pd.DataFrame:
    columns = ["ID", "Quantity", "Code", "Price", "Product", "Description"]
    product_names = ["Apple", "Banana", "Orange", "Pear", "Grape"]
    rng = random.Random(seed)
    code_to_product = {}
    records = []

    for line_number, line in enumerate(s.splitlines(), start=1):
        if not line.strip():
            continue

        parts = re.split(r"\s+", line.strip(), maxsplit=4)
        if len(parts) != 5:
            raise ValueError(
                f"Line {line_number} must contain ID, quantity, code, price, "
                "and description"
            )

        id_value, quantity, code, price, description = (
            part.strip() for part in parts
        )

        try:
            id_value = int(id_value)
            quantity = int(quantity)
            price = int(price)
        except ValueError as exc:
            raise ValueError(
                f"Line {line_number} contains invalid numeric values"
            ) from exc

