import itertools
import math
from pandas import Series


def task_func(elements, subset_size, top_n=2):
    if subset_size <= 0 or subset_size > len(elements):
        return 1, Series([], dtype=int)

    subset_sums = [
        sum(subset)
        for subset in itertools.combinations(elements, subset_size)
    ]

    product_of_sums = math.prod(subset_sums)
    top_sums = Series(sorted(subset_sums, reverse=True)[:max(top_n, 0)])

    return product_of_sums, top_sums

import subprocess
import os
import signal
import time


def task_func(process_name: str) -> int:
    if not process_name:
        return 0

    try:
        result = subprocess.run(
            ["pgrep", "-x", process_name],
            capture_output=True,
            text=True,
            check=False,
        )
    except (OSError, subprocess.SubprocessError):
        return 0

    if result.returncode != 0:
        return 0

    current_pid = os.getpid()
    stopped = 0

    for line in result.stdout.splitlines():
        try:
            pid = int(line.strip())
        except ValueError:
            continue

        if pid == current_pid:
            continue

        try:
            os.kill(pid, signal.SIGTERM)
        except (ProcessLookupError, PermissionError, OSError):
            continue
        else:
            stopped += 1

    time.sleep(1)
    return stopped

