import subprocess
import os
import shutil
from glob import glob


def task_func(src_folder, dst_folder):
    failed_files = []

    if not os.path.isdir(src_folder):
        return {
            "success": False,
            "message": f"Source folder does not exist: {src_folder}",
            "failed_files": [],
        }

    try:
        os.makedirs(dst_folder, exist_ok=True)
    except OSError as exc:
        return {
            "success": False,
            "message": f"Could not create destination folder: {exc}",
            "failed_files": [],
        }

    files = [
        path
        for path in glob(os.path.join(src_folder, "*"))
        if os.path.isfile(path)
    ]

    processes = []

    for file_path in files:
        try:
            process = subprocess.Popen(
                ["gzip", file_path],
                stdout=subprocess.DEVNULL,
                stderr=subprocess.DEVNULL,
            )
            processes.append((file_path, process))
        except OSError:
            failed_files.append(os.path.basename(file_path))

    same_folder = os.path.abspath(src_folder) == os.path.abspath(dst_folder)

    for file_path, process in processes:
        filename = os.path.basename(file_path)
        compressed_path = f"{file_path}.gz"

        try:
            return_code = process.wait()

            if return_code != 0 or not os.path.isfile(compressed_path):
                failed_files.append(filename)
                continue

            if not same_folder:
                destination_path = os.path.join(
                    dst_folder,
                    os.path.basename(compressed_path),
                )
                shutil.move(compressed_path, destination_path)
        except (OSError, shutil.Error):
            failed_files.append(filename)

    success = not failed_files
    if success:
        message = f"Successfully compressed and moved {len(files)} file(s)."
    else:
        message = (
            f"Compression or moving failed for "
            f"{len(failed_files)} file(s)."
        )

    return {
        "success": success,
        "message": message,
        "failed_files": failed_files,
    }

