from collections import Counter

def task_func(json_str, top_n=10):
    """Extract and count URLs from a JSON-serialized dictionary."""
    try:
        data = json.loads(json_str)
    except (TypeError, json.JSONDecodeError) as exc:
        raise ValueError("json_str must contain valid JSON") from exc

    if not isinstance(data, dict):
        raise ValueError("json_str must serialize a dictionary")

    if not isinstance(top_n, int):
        raise TypeError("top_n must be an integer")

    url_pattern = re.compile(r"https?://[^\s<>'\"]+")
    counts = Counter()

    def extract(value):
        if isinstance(value, str):
            for url in url_pattern.findall(value):
                counts[url.rstrip(".,;:!?)]}")] += 1
        elif isinstance(value, dict):
            for key, item in value.items():
                extract(key)
                extract(item)
        elif isinstance(value, list):
            for item in value:
                extract(item)

    extract(data)
    return dict(counts.most_common(max(0, top_n)))

