            if headers is not None:
                try:
                    charset = headers.get_content_charset()
                except AttributeError:
                    charset = None
            content = content.decode(charset or "utf-8", errors="replace")

    document = pq(content)
    rows = [
        {
            "text": anchor.text(),
            "href": anchor.attr("href") or "",
            "fetch_time": fetch_time,
        }
        for anchor in document("a").items()
    ]

    return pd.DataFrame(rows, columns=["text", "href", "fetch_time"])

