import re


def task_func(data_list, seed=None):
    rng = random.Random(seed)
    original_strings = list(data_list)
    modified_strings = []

    for string in original_strings:
        substrings = string.split(",")

        operations = ["replace", "shuffle", "randomize"]
        if len(substrings) > 1:
            operations.append("remove")

        operation = rng.choice(operations)

        if operation == "remove":
            del substrings[rng.randrange(len(substrings))]
        elif operation == "replace":
            substrings[rng.randrange(len(substrings))] = "random_string"
        elif operation == "shuffle":
            rng.shuffle(substrings)
        else:  # randomize
            substrings = rng.sample(substrings, len(substrings))

        modified_strings.append(",".join(substrings))

    return pd.DataFrame(
        {
            "Original String": original_strings,
            "Modified String": modified_strings,
        }
    )

import os
import glob
import shutil
import time

# Constants
FILE_EXTENSIONS = ['.txt', '.csv', '.xlsx', '.docx', '.pdf']


def task_func(my_path: str, days_old: int) -> str:
    if not os.path.exists(my_path):
        raise FileNotFoundError(f"Directory does not exist: {my_path}")
    if not os.path.isdir(my_path):
        raise NotADirectoryError(f"Path is not a directory: {my_path}")
    if days_old < 0:
        raise ValueError("days_old must be non-negative")

    archive_path = os.path.join(my_path, "archive")
    os.makedirs(archive_path, exist_ok=True)

    cutoff_time = time.time() - days_old * 24 * 60 * 60

    for extension in FILE_EXTENSIONS:
        pattern = os.path.join(my_path, f"*{extension}")

        for file_path in glob.glob(pattern):
            if not os.path.isfile(file_path):
                continue

            if os.path.getmtime(file_path) >= cutoff_time:
                continue

            filename = os.path.basename(file_path)
            destination = os.path.join(archive_path, filename)

            if os.path.exists(destination):
                base, extension = os.path.splitext(filename)
                counter = 1

                while True:
                    candidate = os.path.join(
                        archive_path,
                        f"{base}_{counter}{extension}",
                    )
                    if not os.path.exists(candidate):
                        destination = candidate
                        break
                    counter += 1

            shutil.move(file_path, destination)

    return archive_path

import os
import hashlib
import json
from pathlib import Path


def task_func(directory: str) -> str:
    root = Path(directory).expanduser().resolve()

    if not root.is_dir():
        raise NotADirectoryError(f"Not a directory: {directory}")

    output_path = root / "hashes.json"
    hashes = {}

    for file_path in sorted(root.rglob("*")):
        if not file_path.is_file() or file_path.resolve() == output_path:
            continue

        digest = hashlib.sha256()
        with file_path.open("rb") as file:
            for chunk in iter(lambda: file.read(1024 * 1024), b""):
                digest.update(chunk)

        relative_path = file_path.relative_to(root).as_posix()
        hashes[relative_path] = digest.hexdigest()

    with output_path.open("w", encoding="utf-8") as file:
        json.dump(hashes, file, indent=2, sort_keys=True)
        file.write("\n")

    return str(output_path)

