import subprocess
import time
import json
import platform
import re

LOGFILE_PATH = "logfile.log"


def task_func(interval, duration):
    if interval <= 0 or duration <= 0:
        raise ValueError("interval and duration must be greater than zero")

    records = []
    start_time = time.monotonic()
    system = platform.system().lower()

    while time.monotonic() - start_time < duration:
        measurement_start = time.monotonic()
        usage = None

        try:
            if system == "windows":
                output = subprocess.check_output(
                    ["wmic", "cpu", "get", "loadpercentage", "/value"]
                )
                if isinstance(output, bytes):
                    output = output.decode("utf-8", errors="replace")

                match = re.search(
                    r"loadpercentage\s*=\s*([\d.]+)", output, re.IGNORECASE
                )
                if match:
                    usage = float(match.group(1))
            else:
                output = subprocess.check_output(["top", "-bn1"])
                if isinstance(output, bytes):
                    output = output.decode("utf-8", errors="replace")

                match = re.search(r"([\d.]+)\s*id", output, re.IGNORECASE)
                if match:
                    usage = 100.0 - float(match.group(1))

        except (OSError, subprocess.SubprocessError, ValueError):
            usage = None

        if usage is not None:
            records.append(
                {
                    "timestamp": time.time(),
                    "cpu_usage": usage,
                }
            )

        elapsed = time.monotonic() - start_time
        if elapsed >= duration:
            break

        remaining = interval - (time.monotonic() - measurement_start)
        if remaining > 0:
            time.sleep(remaining)

    try:
        with open(LOGFILE_PATH, "w", encoding="utf-8") as logfile:
            json.dump(records, logfile, indent=2)
    except (IOError, OSError):
        return None

    return LOGFILE_PATH

