def task_func(precision=2, seed=0):
    rng = np.random.default_rng(seed)

    a = 0
    while a == 0:
        a = int(rng.integers(-10, 11))

    b = int(rng.integers(-10, 11))
    c = int(rng.integers(-10, 11))

    x = symbols("x")
    solutions = solve(a * x**2 + b * x + c, x)

