import pandas as pd
import numpy as np
from sklearn.linear_model import LinearRegression


def task_func(start_date='2016-01-01', periods=13, freq='WOM-2FRI', sales_data=None):
    """Generate sales data and forecast future sales with linear regression."""
    if isinstance(periods, (bool, np.bool_)) or not isinstance(
        periods, (int, np.integer)
    ) or periods <= 0:
        raise ValueError("periods must be a positive integer")

    try:
        start = pd.Timestamp(start_date)
        if pd.isna(start):
            raise ValueError("start_date must be a valid date")
        pd.date_range(start=start, periods=int(periods), freq=freq)
    except (ValueError, TypeError, OverflowError) as exc:
        raise ValueError("Invalid start_date or frequency") from exc

    if sales_data is None:
        sales = np.arange(1, periods + 1, dtype=float)
    else:
        try:
            sales = np.asarray(sales_data, dtype=float)
        except (TypeError, ValueError) as exc:
            raise ValueError("sales_data must contain numeric values") from exc

        if sales.ndim != 1 or sales.size == 0:
            raise ValueError("sales_data must be a non-empty one-dimensional sequence")
        if sales.size != periods:
            raise ValueError("sales_data length must match periods")
        if not np.all(np.isfinite(sales)):
            raise ValueError("sales_data must contain only finite values")

    X = np.arange(periods, dtype=float).reshape(-1, 1)
    future_X = np.arange(periods, 2 * periods, dtype=float).reshape(-1, 1)

    model = LinearRegression().fit(X, sales)
    return np.asarray(model.predict(future_X), dtype=float)

import re
import glob
from docx import Document


def task_func(directory_path: str) -> int:
    directory = directory_path.rstrip("/\\")
    file_paths = glob.glob(directory + "/*")
    docx_paths = sorted(
        path for path in file_paths
        if path.lower().endswith(".docx")
    )

    for file_path in docx_paths:
        document = Document(file_path)
        processed_parts = set()

        parts = [document.part]
        parts.extend(document.part.related_parts.values())

        for part in parts:
            part_id = id(part)
            if part_id in processed_parts:
                continue
            processed_parts.add(part_id)

            root = getattr(part, "element", None)
            if root is None:
                continue

            for element in root.iter():
                if element.tag.split("}")[-1] == "t" and element.text:
                    element.text = re.sub(r'"', r'\\"', element.text)

        document.save(file_path)

    return len(docx_paths)

