import os
import pathlib
from hashlib import md5
import unicodedata


def task_func(directory):
    directory_path = pathlib.Path(directory)

    if not directory_path.exists():
        raise FileNotFoundError(f"Directory does not exist: {directory}")
    if not directory_path.is_dir():
        raise NotADirectoryError(f"Not a directory: {directory}")

    result = {}

    for file_path in sorted(directory_path.iterdir(), key=lambda path: path.name):
        if not file_path.is_file():
            continue

        normalized_name = unicodedata.normalize(
            "NFKD", file_path.name
        ).encode("ascii", "ignore").decode("ascii")

        if normalized_name in result:
            raise ValueError(
                f"Multiple files normalize to the same name: {normalized_name!r}"
            )

        digest = md5()
        with file_path.open("rb") as file:
            for chunk in iter(lambda: file.read(8192), b""):
                digest.update(chunk)

        result[normalized_name] = {
            "Size": file_path.stat().st_size,
            "MD5 Hash": digest.hexdigest(),
        }

    return result

import os
import re
import hashlib


def task_func(path, delimiter):
    if not isinstance(path, str):
        raise TypeError("path must be a string")
    if not isinstance(delimiter, str):
        raise TypeError("delimiter must be a string")
    if not delimiter:
        raise ValueError("delimiter must not be empty")

    components = re.split(f"({re.escape(delimiter)})", path)
    result = []

    for component in components:
        component_hash = None

        if os.path.isfile(component):
            digest = hashlib.sha256()
            with open(component, "rb") as file:
                for chunk in iter(lambda: file.read(8192), b""):
                    digest.update(chunk)
            component_hash = digest.hexdigest()

        result.append((component, component_hash))

    return result

