import pandas as pd
import itertools
import random


def task_func(colors, states):
    combinations = [
        f"{color}:{state}"
        for color, state in itertools.product(colors, states)
    ]
    random.shuffle(combinations)

    num_columns = min(len(colors), len(states))
    if num_columns == 0:
        return pd.DataFrame()

    total = len(combinations)
    base_size, remainder = divmod(total, num_columns)

    columns = []
    start = 0

    for index in range(num_columns):
        size = base_size + (index < remainder)
        column = combinations[start:start + size]
        columns.append(column)
        start += size

    max_size = max(map(len, columns), default=0)
    data = {
        f"Column_{index + 1}": column + [None] * (max_size - len(column))
        for index, column in enumerate(columns)
    }

    return pd.DataFrame(data)

