import binascii
import hashlib
import re
import os

OUTPUT_DIR = './output'


def task_func(directory: str, pattern: str = r"(?<!Distillr)\\AcroTray\.exe") -> dict:
    regex = re.compile(pattern)
    result = {}

    for root, _, files in os.walk(directory):
        for filename in files:
            file_path = os.path.join(root, filename)

            if regex.search(file_path) is None:
                continue

            digest = hashlib.sha256()
            with open(file_path, "rb") as file:
                for chunk in iter(lambda: file.read(1024 * 1024), b""):
                    digest.update(chunk)

            result[file_path] = binascii.hexlify(digest.digest()).decode("ascii")

    return result

import re
import json
import requests


def task_func(data_url: str) -> list:
    try:
        response = requests.get(data_url)
        text = response.text
        json.loads(text)

        name_pattern = re.compile(r'"name"\s*:\s*"((?:\\.|[^"\\])*)"')

        array_depth = [0] * len(text)
        in_string = [False] * len(text)

        depth = 0
        string = False
        escaped = False

        for index, char in enumerate(text):
            array_depth[index] = depth
            in_string[index] = string

            if string:
                if escaped:
                    escaped = False
                elif char == "\\":
                    escaped = True
                elif char == '"':
                    string = False
            elif char == '"':
                string = True
            elif char == "[":
                depth += 1
            elif char == "]":
                depth -= 1

        names = []
        for match in name_pattern.finditer(text):
            position = match.start()
            if not in_string[position] and array_depth[position] == 0:
                names.append(json.loads(f'"{match.group(1)}"'))

        return names

    except Exception:
        return "Invalid url input"

