import numpy as np
import pandas as pd
from numbers import Integral, Real


def task_func(
    products,
    n_samples=100,
    sales_lower=50,
    sales_upper=200,
    profit_margin_min=0.1,
    profit_margin_max=0.5,
    random_seed=42,
):
    if not isinstance(products, list) or not all(
        isinstance(product, str) for product in products
    ):
        raise TypeError("products must be a list of strings")

    if (
        isinstance(n_samples, bool)
        or not isinstance(n_samples, Integral)
        or n_samples <= 0
    ):
        raise ValueError("n_samples must be a positive integer")

    bounds = (
        sales_lower,
        sales_upper,
        profit_margin_min,
        profit_margin_max,
    )
    if any(isinstance(value, bool) or not isinstance(value, Real) for value in bounds):
        raise TypeError("sales and profit-margin bounds must be numeric")

    if sales_lower > sales_upper:
        raise ValueError("sales_lower must not be greater than sales_upper")

    columns = ["product", "total_sales", "total_profit"]
    if not products:
        return pd.DataFrame(columns=columns)

    rng = np.random.default_rng(random_seed)
    rows = []

    for product in products:
        if isinstance(sales_lower, Integral) and isinstance(sales_upper, Integral):
            sales = rng.integers(
                sales_lower,
                sales_upper + 1,
                size=n_samples,
            )
        else:
            sales = rng.uniform(
                sales_lower,
                sales_upper,
                size=n_samples,
            )

        margins = rng.uniform(
            profit_margin_min,
            profit_margin_max,
            size=n_samples,
        )

        rows.extend(
            {
                "product": product,
                "sales": float(sale),
                "profit": float(sale * margin),
            }
            for sale, margin in zip(sales, margins)
        )

    return (
        pd.DataFrame(rows)
        .groupby("product", as_index=False)
        .agg(
            total_sales=("sales", "sum"),
            total_profit=("profit", "sum"),
        )
        .sort_values("total_profit", ascending=False)
        .reset_index(drop=True)
    )

