import pandas as pd
import matplotlib.pyplot as plt
from sklearn.decomposition import PCA
def task_func(data_matrix, n_components=2):
    import numpy as np
    from numbers import Integral

    if isinstance(n_components, bool) or not isinstance(n_components, Integral):
        raise ValueError("n_components must be a positive integer.")
    if n_components <= 0:
        raise ValueError("n_components must be a positive integer.")

    try:
        if isinstance(data_matrix, pd.DataFrame):
            if data_matrix.ndim != 2:
                raise ValueError("data_matrix must be a 2D matrix.")
            index = data_matrix.index
            matrix = data_matrix.apply(pd.to_numeric, errors="coerce")
        else:
            raw_matrix = np.asarray(data_matrix)
            if raw_matrix.ndim != 2:
                raise ValueError("data_matrix must be a 2D matrix.")
            index = None
            matrix = pd.DataFrame(raw_matrix).apply(
                pd.to_numeric, errors="coerce"
            )

        if matrix.empty or matrix.isna().any().any():
            raise ValueError(
                "data_matrix must be a non-empty numeric matrix."
            )

        values = matrix.to_numpy(dtype=float)
        if not np.isfinite(values).all():
            raise ValueError(
                "data_matrix must contain only finite numeric values."
            )
    except (TypeError, ValueError, OverflowError) as exc:
        raise ValueError(
            "data_matrix must be a non-empty numeric 2D matrix."
        ) from exc

    if n_components > min(values.shape):
        raise ValueError(
            "n_components cannot exceed the number of samples or features."
        )

    pca = PCA(n_components=n_components)
    transformed = pca.fit_transform(values)

    columns = [
        f"Component {component}"
        for component in range(1, n_components + 1)
    ]
    result = pd.DataFrame(transformed, columns=columns, index=index)
    result["Mean"] = transformed.mean(axis=1)

    _, ax = plt.subplots()
    cumulative_variance = pca.explained_variance_ratio_.cumsum()
    ax.plot(
        range(1, n_components + 1),
        cumulative_variance,
        marker="o",
    )
    ax.set_xlabel("Number of Components")
    ax.set_ylabel("Cumulative Explained Variance")

    return result, ax

