import os
import sys
import importlib
from pkgutil import iter_modules


def task_func(package_name):
    try:
        package = importlib.import_module(package_name)
    except ImportError as exc:
        raise ImportError(
            f"Could not import package '{package_name}'. "
            f"Please install it with: pip install {package_name}"
        ) from exc

    package_paths = getattr(package, "__path__", None)

    if package_paths is not None:
        locations = list(package_paths)
    else:
        package_file = getattr(package, "__file__", None)
        locations = [os.path.dirname(package_file)] if package_file else []

    locations = list(dict.fromkeys(path for path in locations if path))

    for location in locations:
        if location not in sys.path:
            sys.path.append(location)

    module_names = []
    seen = set()

    for module_info in iter_modules(locations):
        if module_info.name not in seen:
            seen.add(module_info.name)
            module_names.append(module_info.name)

    return module_names

