import matplotlib.pyplot as plt

# Constants
HEADERS = {
    'accept': 'application/json'
}


def task_func(url, parameters):
    if not isinstance(url, str) or not url.strip():
        raise Exception("URL must be a non-empty string")

    if parameters is not None and not isinstance(parameters, dict):
        raise Exception("Parameters must be a dictionary or None")

    try:
        response = requests.get(
            url,
            params=parameters,
            headers=HEADERS,
            timeout=30
        )

        status_code = getattr(response, "status_code", 200)
        if not isinstance(status_code, int) or not 200 <= status_code < 300:
            raise Exception(f"Request failed with status code {status_code}")

        try:
            payload = response.json()
        except Exception:
            payload = json.loads(response.text)

    except Exception as exc:
        raise Exception(f"Unable to access or parse the URL: {exc}") from exc

    if payload is None or payload == "":
        raise Exception("The API returned empty data")

    if isinstance(payload, dict):
        for key in ("data", "results", "items", "records"):
            if key in payload:
                payload = payload[key]
                break
        else:
            payload = [payload]

    if not isinstance(payload, list) or not payload:
        raise Exception("Invalid or empty API data")

    if not all(isinstance(record, dict) for record in payload):
        raise Exception("API data must contain record objects")

    dataframe = pd.DataFrame(payload)
    if dataframe.empty:
        raise Exception("The resulting DataFrame is empty")

    numerical_data = dataframe.select_dtypes(include="number")
    if numerical_data.shape[1] < 2:
        raise Exception(
            "At least two numerical columns are required for a correlation heatmap"
        )

    try:
        correlation_matrix = numerical_data.corr()
        axes = sns.heatmap(
            correlation_matrix,
            annot=True,
            cmap="coolwarm"
        )
        plt.show()
    except Exception as exc:
        raise Exception(f"Unable to create heatmap: {exc}") from exc

    return dataframe, axes

import random
import re

def task_func(text, seed=None):
    rng = random.Random(seed)

    def scramble(match):
        word = match.group(0)
        if len(word) <= 3:
            return word

        middle = list(word[1:-1])
        rng.shuffle(middle)
        return word[0] + "".join(middle) + word[-1]

    return re.sub(r"\b\w+\b", scramble, text)

import subprocess
import os
import time
import glob


def task_func(r_script_path: str, output_path: str, duration: int) -> (bool, str):
    success_message = "File generated successfully within the specified duration."
    failure_message = "File not generated within the specified duration."

    def output_exists() -> bool:
        if glob.has_magic(output_path):
            return bool(glob.glob(output_path))
        return os.path.exists(output_path)

    if output_exists():
        return True, success_message

    if duration <= 0:
        return False, failure_message

    start_time = time.monotonic()
    deadline = start_time + duration

    try:
        process = subprocess.Popen(["Rscript", r_script_path])
    except OSError:
        return False, failure_message

    try:
        while True:
            if output_exists():
                return True, success_message

            remaining = deadline - time.monotonic()
            if remaining <= 0:
                return False, failure_message

            if process.poll() is not None:
                return False, failure_message

            time.sleep(min(0.05, remaining))
    finally:
        if process.poll() is None:
            process.terminate()
