import numpy as np
import matplotlib.pyplot as plt


def task_func(P, T):
    if not isinstance(P, (np.ndarray, np.matrix)):
        raise TypeError("P must be a NumPy array or matrix.")
    if not isinstance(T, (np.ndarray, np.matrix)):
        raise TypeError("T must be a NumPy array or matrix.")

    P = np.asarray(P)
    T = np.asarray(T)

    if P.ndim != 2:
        raise ValueError("P must be a 2D matrix.")
    if T.ndim != 3:
        raise ValueError("T must be a 3D tensor.")
    if T.shape[2] != 3:
        raise ValueError("The last dimension of T must have size 3.")
    if P.shape[1] != T.shape[0]:
        raise ValueError("P.shape[1] must equal T.shape[0].")
    if P.shape[0] != T.shape[1]:
        raise ValueError("P.shape[0] must equal T.shape[1].")
    if P.size == 0 or T.size == 0:
        raise ValueError("P and T must not be empty.")
    if not np.issubdtype(P.dtype, np.number):
        raise TypeError("P must contain numeric values.")
    if not np.issubdtype(T.dtype, np.number):
        raise TypeError("T must contain numeric values.")
    if np.iscomplexobj(P) or np.iscomplexobj(T):
        raise TypeError("P and T must contain real-valued numbers.")

    result = np.einsum("nm,mnk->nk", P, T)

    fig = plt.figure()
    ax = fig.add_subplot(111, projection="3d")
    ax.scatter(result[:, 0], result[:, 1], result[:, 2])

    ax.set_xlabel("X")
    ax.set_ylabel("Y")
    ax.set_zlabel("Z")
    ax.set_title("Matrix-Tensor Product")

    return result, ax

