    step,
    columns=["Timestamp", "Sensor1", "Sensor2", "Sensor3", "SensorStatus"],
    sensor_statuses=["OK", "MAINTENANCE_REQUIRED", "ERROR"],
    random_seed=42,
):
    if len(columns) != 5:
        raise ValueError("columns must contain exactly five names.")

    if len(sensor_statuses) == 0:
        raise ValueError("sensor_statuses must not be empty.")

    if isinstance(step, (int, float, np.integer, np.floating)) and not isinstance(step, bool):
        if not np.isfinite(step) or step <= 0:
            raise ValueError("step must be a positive finite number.")
        step = pd.to_timedelta(step, unit="s")

    try:
        step = pd.Timedelta(step)
    except (TypeError, ValueError):
        raise ValueError("step must be a valid positive time interval.") from None

    if step <= pd.Timedelta(0):
        raise ValueError("step must be positive.")

    timestamps = pd.date_range(
        start=start_time,
        end=end_time,
        freq=step,
