        columns[2]: np.cos(seconds) + rng.normal(0, noise_scale, count),
        columns[3]: np.tan(seconds) + rng.normal(0, noise_scale, count),
        columns[4]: rng.choice(sensor_statuses, size=count),
    }

    return pd.DataFrame(data, columns=columns)

