def task_func(rows, columns):
    if isinstance(rows, bool) or not isinstance(rows, (int, np.integer)):
        raise TypeError("rows must be a non-negative integer")
    if isinstance(columns, bool) or not isinstance(columns, (int, np.integer)):
        raise TypeError("columns must be a non-negative integer")
    if rows < 0 or columns < 0:
        raise ValueError("rows and columns must be non-negative")

    rows = int(rows)
    columns = int(columns)

    def random_int():
        return int(np.random.randint(0, 10))

    def random_value(data_type):
        if data_type is str:
            return "".join(choice("abcdefghijklmnopqrstuvwxyz") for _ in range(5))
        if data_type is int:
            return random_int()
        if data_type is float:
            return float(random_int())
        if data_type is list:
            length = int(np.random.randint(1, 6))
            return [random_int() for _ in range(length)]
        if data_type is tuple:
            length = int(np.random.randint(1, 6))
            return tuple(random_int() for _ in range(length))
        if data_type is dict:
            length = int(np.random.randint(1, 6))
            keys = np.random.choice(10, size=length, replace=False)
            return {int(key): random_int() for key in keys}
        if data_type is set:
            length = int(np.random.randint(1, 6))
            values = np.random.choice(10, size=length, replace=False)
            return {int(value) for value in values}
        raise ValueError(f"Unsupported data type: {data_type}")

    column_names = [f"col{i}" for i in range(columns)]
    data = {
        column_name: [
            random_value(choice(DATA_TYPES))
            for _ in range(rows)
        ]
        for column_name in column_names
    }

    return pd.DataFrame(data, index=range(rows), columns=column_names)

