import re
import os
import glob


def task_func(dir_path: str) -> list:
    files = [
        path
        for path in glob.glob(os.path.join(dir_path, "*"))
        if os.path.isfile(path)
    ]

    renames = []
    targets = {}

    for file_path in files:
        old_name = os.path.basename(file_path)
        new_name = re.sub(r"[^A-Za-z0-9]", "", old_name)

        if not new_name:
            raise ValueError(
                f"Cannot rename {old_name!r}: resulting name is empty"
            )

        if new_name in targets:
            raise FileExistsError(
                f"Multiple files would be renamed to {new_name!r}"
            )

        new_path = os.path.join(dir_path, new_name)
        targets[new_name] = file_path
        renames.append((file_path, new_path, new_name))

    for file_path, new_path, new_name in renames:
        if new_path != file_path and os.path.exists(new_path):
            raise FileExistsError(f"Target file already exists: {new_name}")

    for file_path, new_path, _ in renames:
        if new_path != file_path:
            os.rename(file_path, new_path)

    return [new_name for _, _, new_name in renames]

