import pandas as pd
import numpy as np
import matplotlib.pyplot as plt


def task_func(start_time, end_time, step, amplitude, period, seed=0):
    """Generate and plot a sinusoidal time series with the requested seasonality."""

    def to_utc_timestamp(value):
        try:
            timestamp = pd.Timestamp(value)
        except Exception as exc:
            raise ValueError("Invalid datetime value") from exc

        if pd.isna(timestamp):
            raise ValueError("Datetime value cannot be missing")

        if timestamp.tzinfo is None:
            return timestamp.tz_localize("UTC")
        return timestamp.tz_convert("UTC")

    def to_positive_timedelta(value, name):
        if isinstance(value, (bool, np.bool_)):
            raise ValueError(f"{name} must be positive")

        try:
            if isinstance(value, (int, float, np.integer, np.floating)):
                duration = pd.to_timedelta(float(value), unit="s")
            else:
                duration = pd.to_timedelta(value)
        except Exception as exc:
            raise ValueError(f"Invalid {name}") from exc

        if pd.isna(duration) or duration <= pd.Timedelta(0):
            raise ValueError(f"{name} must be positive")

        return duration

    start = to_utc_timestamp(start_time)
    end = to_utc_timestamp(end_time)

    if end < start:
        raise ValueError("end_time must not precede start_time")

    step_delta = to_positive_timedelta(step, "step")
    period_delta = to_positive_timedelta(period, "period")

    if isinstance(amplitude, (bool, np.bool_)):
        raise ValueError("amplitude must be numeric")

    try:
        amplitude_value = float(amplitude)
    except (TypeError, ValueError) as exc:
        raise ValueError("amplitude must be numeric") from exc

    if not np.isfinite(amplitude_value):
        raise ValueError("amplitude must be finite")

    timestamps = pd.date_range(
        start=start,
        end=end,
        freq=step_delta,
        inclusive="both",
    )

    elapsed_seconds = (timestamps - timestamps[0]).total_seconds()
    period_seconds = period_delta.total_seconds()

    values = amplitude_value * np.sin(
        2 * np.pi * elapsed_seconds / period_seconds
    )

    data = pd.DataFrame(
        {
            "Timestamp": timestamps,
            "Value": values,
        }
    )

    fig, ax = plt.subplots()
    ax.plot(data["Timestamp"], data["Value"])
    ax.set_xlabel("Timestamp")
    ax.set_ylabel("Value")
    ax.set_title("Time Series with Seasonality")
    ax.grid(True)
    fig.autofmt_xdate()

    return ax

