import subprocess
import psutil
import time
import os
import math


def task_func(script_path: str, timeout=10) -> dict:
    if not os.path.exists(script_path):
        raise FileNotFoundError(f"Script not found: {script_path}")

    if isinstance(timeout, bool) or not isinstance(timeout, (int, float)):
        raise TypeError("timeout must be a positive finite number")
    if not math.isfinite(timeout) or timeout <= 0:
        raise ValueError("timeout must be a positive finite number")

    process = subprocess.Popen(["bash", script_path])
    monitored_process = psutil.Process(process.pid)

    cpu_usage = 0.0
    memory_usage = 0
    start_time = time.monotonic()
    poll_interval = 0.1

    try:
        monitored_process.cpu_percent(None)

        while process.poll() is None:
            elapsed = time.monotonic() - start_time
            if elapsed >= timeout:
                process.terminate()
                try:
                    process.wait(timeout=1)
                except subprocess.TimeoutExpired:
                    process.kill()
                    process.wait()
                break

            try:
                if (
                    not monitored_process.is_running()
                    or monitored_process.status() == psutil.STATUS_ZOMBIE
                ):
                    break

                cpu_usage += monitored_process.cpu_percent(None)
                memory_usage += monitored_process.memory_info().rss
            except (
                psutil.NoSuchProcess,
                psutil.ZombieProcess,
                psutil.AccessDenied,
            ):
                break

            remaining = timeout - (time.monotonic() - start_time)
            if remaining > 0:
                time.sleep(min(poll_interval, remaining))

    finally:
        if process.poll() is None:
            process.terminate()
            try:
                process.wait(timeout=1)
            except subprocess.TimeoutExpired:
                process.kill()
                process.wait()

    return {
        "CPU Usage": cpu_usage,
        "Memory Usage": memory_usage,
    }

