# Constants
REPLACE_NONE = "None"

def task_func(json_str):
    email_pattern = re.compile(
        r"(?<![A-Za-z0-9._%+-])"
        r"[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Za-z]{2,}"
        r"(?![A-Za-z0-9.-])"
    )

    def process(value):
        if isinstance(value, dict):
            return {
                key: process(item)
                for key, item in value.items()
                if item is not None
            }

        if isinstance(value, list):
            return [process(item) for item in value if item is not None]

        if isinstance(value, str):
            return email_pattern.sub(REPLACE_NONE, value)

        return value

    processed_data = process(json.loads(json_str))
    value_counts = Counter()

    def count_values(value):
        if isinstance(value, dict):
            for item in value.values():
                count_values(item)
        elif isinstance(value, list):
            for item in value:
                count_values(item)
        elif value is not None:
            value_counts[value] += 1

    count_values(processed_data)

    return {
        "data": processed_data,
        "value_counts": value_counts,
    }

