import pandas as pd
import re

# Function to replace acronyms in DataFrame
def task_func(data, mapping):
    if not isinstance(data, pd.DataFrame):
        raise TypeError("data must be a pandas DataFrame")
    if not hasattr(mapping, "items"):
        raise TypeError("mapping must be a dictionary-like object")

    keys = [key for key in mapping if isinstance(key, str) and key]
    if not keys:
        return data.copy()

    pattern = re.compile(
        r"(?<!\w)(?:"
        + "|".join(re.escape(key) for key in sorted(keys, key=len, reverse=True))
        + r")(?!\w)"
    )

    def replace_acronyms(value):
        if isinstance(value, str):
            return pattern.sub(
                lambda match: str(mapping[match.group(0)]),
                value,
            )
        return value

    return data.applymap(replace_acronyms)

import random
import bisect
from array import array


def task_func(n=10, total=100):
    if isinstance(n, bool) or not isinstance(n, int) or n < 1:
        raise ValueError("n must be a positive integer")
    if isinstance(total, bool) or not isinstance(total, int):
        raise ValueError("total must be an integer")
    if total < 0:
        raise ValueError("total must be non-negative")

    if n == 1:
        numbers = [total]
    else:
        numbers = None

        for _ in range(1000):
            candidate = [random.randint(0, total) for _ in range(n - 1)]
            candidate.append(total - sum(candidate))

            if candidate[-1] >= 0:
                numbers = candidate
                break

        if numbers is None:
            cuts = sorted(random.randint(0, total) for _ in range(n - 1))
            points = [0, *cuts, total]
            numbers = [
                points[index + 1] - points[index]
                for index in range(n)
            ]

    sorted_numbers = array("i", sorted(numbers))
    new_number = random.randint(0, total)
    insertion_position = bisect.bisect_left(sorted_numbers, new_number)

    return sorted_numbers, insertion_position

