        raise ValueError("'value' must contain valid numeric data") from exc

    if numeric_values.isna().any() or (~numeric_values.abs().ne(float("inf"))).any():
        raise ValueError("'value' must contain finite values")

    if decomposition_model == "multiplicative" and (numeric_values <= 0).any():
        raise ValueError(
            "multiplicative decomposition requires strictly positive values"
        )

    name = (offset.name or "").upper()

    if name.startswith("W"):
        period = 52
    elif name.startswith("D"):
        period = 7
    elif name.startswith("B"):
        period = 5
    elif name.startswith("H"):
        period = 24
    elif name.startswith(("T", "MIN")):
        period = 60
    elif name.startswith("S"):
        period = 60
    elif name.startswith("M"):
        period = 12
    elif name.startswith("Q"):
        period = 4
    else:
        raise ValueError("Unable to determine a seasonal period from freq")

    if len(numeric_values) < 2 * period:
        raise ValueError("Not enough observations for seasonal decomposition")

    try:
        result = seasonal_decompose(
            numeric_values,
            model=decomposition_model,
            period=period,
        )
        axes = result.plot().axes[0]
    except (TypeError, ValueError) as exc:
        raise ValueError("Unable to decompose the time series") from exc

    return result, axes

