import re
from datetime import time


def task_func(logs: list):
    timestamp_pattern = re.compile(
        r"(?<!\d)([01]\d|2[0-3]):([0-5]\d):([0-5]\d)(?!\d)"
    )
    error_pattern = re.compile(r"\berror\b", re.IGNORECASE)

    error_times = []

    for log in logs:
        if not isinstance(log, str) or not error_pattern.search(log):
            continue

        match = timestamp_pattern.search(log)
        if match:
            hours, minutes, seconds = map(int, match.groups())
            error_times.append(time(hours, minutes, seconds))

    if not error_times:
        return {"list": [], "time": None}

    total_seconds = sum(
        error_time.hour * 3600
        + error_time.minute * 60
        + error_time.second
        for error_time in error_times
    )
    average_seconds = (total_seconds + len(error_times) // 2) // len(error_times)
    average_seconds %= 24 * 60 * 60

    return {
        "list": error_times,
        "time": time(
            average_seconds // 3600,
            (average_seconds % 3600) // 60,
            average_seconds % 60,
        ),
    }

import os
import re
from pathlib import Path


def task_func(dir_path: str, predicates: list) -> dict:
    directory = Path(dir_path)

    if not directory.is_dir():
        raise FileNotFoundError(dir_path)

    valid_predicates = []
    seen = set()

    for predicate in predicates or []:
        if isinstance(predicate, str):
            try:
                compiled = re.compile(predicate)
            except re.error:
                continue
            key = ("regex", compiled.pattern, compiled.flags)
            if key not in seen:
                seen.add(key)
                valid_predicates.append(compiled)
        elif isinstance(predicate, re.Pattern):
            key = ("regex", predicate.pattern, predicate.flags)
            if key not in seen:
                seen.add(key)
                valid_predicates.append(predicate)
        elif callable(predicate):
            key = ("callable", id(predicate))
            if key not in seen:
                seen.add(key)
                valid_predicates.append(predicate)

    if not valid_predicates:
        raise ValueError("No valid predicates provided")

    result = {}

    for name in os.listdir(directory):
        result[name] = [
            bool(predicate.search(name))
            if isinstance(predicate, re.Pattern)
            else bool(predicate(name))
            for predicate in valid_predicates
        ]

    return result

