# Constants
COLUMNS = ['A', 'B', 'C', 'D', 'E']


def task_func(df, tuples, n_plots):
    if not isinstance(df, pd.DataFrame):
        raise TypeError("df must be a pandas DataFrame")

    missing_columns = [column for column in COLUMNS if column not in df.columns]
    if missing_columns:
        raise KeyError(f"Missing columns: {missing_columns}")

    if isinstance(n_plots, bool) or not isinstance(n_plots, int):
        raise TypeError("n_plots must be a non-negative integer")
    if n_plots < 0:
        raise ValueError("n_plots must be non-negative")

    column_pairs = list(combinations(COLUMNS, 2))
    if n_plots > len(column_pairs):
        raise ValueError(f"n_plots cannot exceed {len(column_pairs)}")

    removal_mask = pd.Series(False, index=df.index)

    for values in tuples:
        try:
            values = tuple(values)
        except TypeError as error:
            raise ValueError("Each filtering tuple must be iterable") from error

        if len(values) != len(COLUMNS):
            raise ValueError(
                f"Each filtering tuple must contain {len(COLUMNS)} values"
            )

        row_mask = pd.Series(True, index=df.index)

        for column, value in zip(COLUMNS, values):
            if pd.isna(value):
                row_mask &= df[column].isna()
            else:
                row_mask &= df[column].eq(value).fillna(False)

        removal_mask |= row_mask

    filtered_df = df.loc[~removal_mask].copy().reset_index(drop=True)
    selected_pairs = sample(column_pairs, n_plots)

    for x_column, y_column in selected_pairs:
        plt.figure()
        plt.plot(filtered_df[x_column], filtered_df[y_column])
        plt.xlabel(x_column)
        plt.ylabel(y_column)
        plt.title(f"{y_column} vs {x_column}")

    return filtered_df, selected_pairs

