import ast
import re


def task_func(text_file: str) -> list:
    with open(text_file, "r", encoding="utf-8") as file:
        text = file.read()

    token_pattern = re.compile(
        r"""'(?:\\.|[^'\\])*'|"(?:\\.|[^"\\])*"|\{|\}""",
        re.DOTALL,
    )

    stack = []
    spans = []

    for match in token_pattern.finditer(text):
        token = match.group()
        if token == "{":
            stack.append(match.start())
        elif token == "}" and stack:
            spans.append((stack.pop(), match.end()))

    dictionaries = []
    accepted_spans = []

    for start, end in sorted(spans):
        if any(
            outer_start <= start and end <= outer_end
            for outer_start, outer_end in accepted_spans
        ):
            continue

        try:
            value = ast.literal_eval(text[start:end])
        except (SyntaxError, ValueError, TypeError):
            continue

        if isinstance(value, dict):
            dictionaries.append(value)
            accepted_spans.append((start, end))

    return dictionaries

