        if not math.isfinite(float(epoch_milliseconds)):
            raise ValueError("epoch_milliseconds must be finite")
    except (OverflowError, TypeError, ValueError) as exc:
        raise ValueError("Invalid epoch timestamp") from exc

    if epoch_milliseconds != int(epoch_milliseconds):
        raise ValueError("epoch_milliseconds must represent an integer timestamp")

    try:
        current_datetime = datetime.now()
        start_datetime = datetime.fromtimestamp(int(epoch_milliseconds) / 1000)
    except (OverflowError, OSError, ValueError) as exc:
        raise ValueError("Invalid epoch timestamp") from exc

    if start_datetime > current_datetime:
        raise ValueError("epoch_milliseconds cannot be in the future")

    try:
        products = list(products)
    except TypeError as exc:
        raise ValueError("products must be an iterable of five strings") from exc

    if len(products) != 5 or any(
        not isinstance(product, str) or not product for product in products
    ):
        raise ValueError("products must contain exactly five non-empty strings")

    rng = random.Random(random_seed)
    records = []
