            current_date.year, current_date.month, current_date.day
        )
        for product in products:
            records.append(
                {
                    "Product": product,
                    "Date": date_value,
                    "Sales": rng.randint(10, 50),
                }
            )
        current_date += timedelta(days=1)

    return pd.DataFrame(records, columns=["Product", "Date", "Sales"])

