# Constants
STOPWORDS = set(stopwords.words('english'))


def task_func(directory_path):
    if not os.path.isdir(directory_path):
        raise NotADirectoryError(f"Not a directory: {directory_path}")

    unique_words = set()
    word_pattern = re.compile(r"[a-z]+")

    for filename in os.listdir(directory_path):
        file_path = os.path.join(directory_path, filename)

        if not os.path.isfile(file_path) or not filename.lower().endswith(".txt"):
            continue

        with open(file_path, "r", encoding="utf-8") as file:
            text = file.read().lower()

        for word in word_pattern.findall(text):
            if word not in STOPWORDS:
                unique_words.add(word)

    return len(unique_words)

import re
import nltk
from gensim.models import Word2Vec
# Constants
ALPHANUMERIC = re.compile('[\W_]+')


def task_func(texts, stopwords=None):
    """Train and return a Word2Vec model from cleaned texts."""
    if stopwords is None:
        stopwords = nltk.corpus.stopwords.words("english")

    stopword_set = {word.lower() for word in stopwords}
    sentences = []

    for text in texts:
        if not isinstance(text, str):
            raise TypeError("Each item in texts must be a string.")

        cleaned_text = ALPHANUMERIC.sub(" ", text).lower()
        tokens = [
            token
            for token in cleaned_text.split()
            if token not in stopword_set
        ]

        if tokens:
            sentences.append(tokens)

    if not sentences:
        raise ValueError("No usable tokens remain after text cleaning.")

    return Word2Vec(
        sentences=sentences,
        vector_size=100,
        window=5,
        min_count=1,
        workers=1,
    )

