        index=shuffled_animals,
        columns=shuffled_foods,
    )

import seaborn as sns
from random import sample

# Constants
COLUMNS = ['A', 'B', 'C', 'D', 'E']


def task_func(df, tuples, n_plots):
    """Remove matching rows and generate random pairplots."""
    if isinstance(n_plots, bool) or not isinstance(n_plots, int) or n_plots < 0:
        raise ValueError("n_plots must be a non-negative integer.")

    missing_columns = [column for column in COLUMNS if column not in df.columns]
    if missing_columns:
        raise ValueError(f"Missing required columns: {missing_columns}")

    patterns = list(tuples)
    for pattern in patterns:
        try:
            if len(pattern) != len(COLUMNS):
                raise ValueError
        except (TypeError, ValueError) as exc:
            raise ValueError(
                "Each tuple must contain exactly one value for every column."
            ) from exc

    filtered_df = df.copy()

    for pattern in patterns:
        matches = filtered_df[COLUMNS].eq(list(pattern)).all(axis=1)
        filtered_df = filtered_df.loc[~matches]

    pairs = [
        (COLUMNS[i], COLUMNS[j])
        for i in range(len(COLUMNS))
        for j in range(i + 1, len(COLUMNS))
    ]

    if n_plots > len(pairs):
        raise ValueError(
            f"n_plots cannot exceed {len(pairs)} unique column pairs."
        )

    axes = []
    for first, second in sample(pairs, n_plots):
        grid = sns.pairplot(
            filtered_df,
            x_vars=[first],
            y_vars=[second],
        )
        axes.append(grid.axes[0, 0])

    return filtered_df, axes

