import struct

KEYS = ['470FC614', '4A0FC614', '4B9FC614', '4C8FC614', '4D7FC614']


def task_func(hex_keys=KEYS, seed=42):
    if not hex_keys:
        raise ValueError("hex_keys must not be empty")

    for key in hex_keys:
        if (
            not isinstance(key, str)
            or len(key) != 8
            or any(char not in "0123456789abcdefABCDEF" for char in key)
        ):
            raise ValueError(f"Invalid hexadecimal string: {key!r}")

    selected_key = random.Random(seed).choice(hex_keys)
