import numpy as np
from scipy import stats


def task_func(L):
    """Calculate the mode of all elements in a nested list."""
    def flatten(items):
        for item in items:
            if isinstance(item, (list, tuple, np.ndarray)):
                yield from flatten(item)
            else:
                yield item

    values = list(flatten(L))
    if not values:
        raise ValueError("Cannot calculate the mode of an empty list.")

    return int(stats.mode(values, keepdims=False).mode)

