import socket
import select
import queue
from datetime import datetime, timedelta


def task_func(
    server_address="localhost", server_port=12345, buffer_size=1024, run_duration=5
):
    start_time = datetime.now()
    server_socket = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
    clients = set()
    outgoing = {}
    pending = {}

    def close_client(client_socket):
        clients.discard(client_socket)
        outgoing.pop(client_socket, None)
        pending.pop(client_socket, None)
        try:
            client_socket.close()
        except OSError:
            pass

    try:
        server_socket.setsockopt(socket.SOL_SOCKET, socket.SO_REUSEADDR, 1)
        server_socket.bind((server_address, server_port))
        server_socket.listen()
        server_socket.setblocking(False)

        deadline = start_time + timedelta(seconds=max(0, run_duration))

        while datetime.now() < deadline:
            client_list = list(clients)
            writable = [
                client_socket
                for client_socket in client_list
                if pending.get(client_socket) is not None
                or not outgoing[client_socket].empty()
            ]
            remaining = max(
                0.0, (deadline - datetime.now()).total_seconds()
            )

            try:
                readable, writable_ready, exceptional = select.select(
                    [server_socket] + client_list,
                    writable,
                    [server_socket] + client_list,
                    remaining,
                )
            except (OSError, ValueError):
                break

            if server_socket in exceptional:
                break

            if server_socket in readable:
                while True:
                    try:
                        client_socket, _ = server_socket.accept()
                        client_socket.setblocking(False)
                        clients.add(client_socket)
                        outgoing[client_socket] = queue.Queue()
                        pending[client_socket] = None
                    except BlockingIOError:
                        break
                    except OSError:
                        break

            for client_socket in exceptional:
                if client_socket is not server_socket:
                    close_client(client_socket)

            for client_socket in readable:
                if client_socket is server_socket or client_socket not in clients:
                    continue

                try:
                    data = client_socket.recv(buffer_size)
                    if not data:
                        close_client(client_socket)
                        continue

                    timestamp = datetime.now().isoformat().encode("utf-8")
                    outgoing[client_socket].put(data + b" " + timestamp)
                except (BlockingIOError, InterruptedError):
                    continue
                except (OSError, ValueError):
                    close_client(client_socket)

            for client_socket in writable_ready:
                if client_socket not in clients:
                    continue

                try:
                    while True:
                        if pending[client_socket] is None:
                            if outgoing[client_socket].empty():
                                break
                            pending[client_socket] = (
                                outgoing[client_socket].get_nowait()
                            )

                        sent = client_socket.send(pending[client_socket])
                        if sent == 0:
                            break

                        pending[client_socket] = pending[client_socket][sent:]
                        if not pending[client_socket]:
                            pending[client_socket] = None
                        else:
                            break
                except (BlockingIOError, InterruptedError):
                    continue
                except (OSError, ValueError):
                    close_client(client_socket)

    except OSError as error:
        elapsed = (datetime.now() - start_time).total_seconds()
        return f"Server failed after {elapsed:.2f} seconds: {error}"
    finally:
        for client_socket in list(clients):
            close_client(client_socket)

        try:
            server_socket.close()
        except OSError:
            pass

    elapsed = (datetime.now() - start_time).total_seconds()
    return f"Server completed after {elapsed:.2f} seconds."

import numpy as np
import pandas as pd
import matplotlib.pyplot as plt


def task_func(N=100, CATEGORIES=["A", "B", "C", "D", "E"], seed=42):
    if isinstance(N, bool) or not isinstance(N, (int, np.integer)):
        raise TypeError("N must be a non-negative integer")
    if N < 0:
        raise ValueError("N must be non-negative")
    if len(CATEGORIES) == 0:
        raise ValueError("CATEGORIES must not be empty")
    if len(set(CATEGORIES)) != len(CATEGORIES):
        raise ValueError("CATEGORIES must contain unique values")

    rng = np.random.default_rng(seed)

    x = rng.random(N)
    y = rng.random(N)

    if N < len(CATEGORIES):
        categories = list(rng.choice(CATEGORIES, size=N, replace=False))
    else:
        categories = list(CATEGORIES)
        categories.extend(
            rng.choice(CATEGORIES, size=N - len(CATEGORIES), replace=True)
        )
        rng.shuffle(categories)

    df = pd.DataFrame(
        {
            "x": x,
            "y": y,
            "category": categories,
        }
    )

    _, ax = plt.subplots()

    for category in CATEGORIES:
        subset = df[df["category"] == category]
        if not subset.empty:
            ax.scatter(
                subset["x"],
                subset["y"],
                label=str(category),
            )

    ax.set_xlabel("x")
    ax.set_ylabel("y")
    if not df.empty:
        ax.legend(title="category")

    return df, ax

import pandas as pd
import numpy as np
import codecs
import re
import datetime


def task_func(start_year=1980, end_year=2000, email_domain='example.com',
              latin_names=['Sopetón', 'Méndez', 'Gómez', 'Pérez', 'Muñoz'],
              other_names=['Smith', 'Johnson', 'Williams', 'Brown', 'Jones'],
              rng_seed=None):
    if isinstance(start_year, bool) or isinstance(end_year, bool):
        raise TypeError("start_year and end_year must be integers")
    if not isinstance(start_year, int) or not isinstance(end_year, int):
        raise TypeError("start_year and end_year must be integers")
    if start_year < 0 or end_year < start_year:
        raise ValueError("Years must satisfy 0 <= start_year <= end_year")

    if not isinstance(email_domain, str) or not email_domain.strip():
        raise ValueError("email_domain must be a non-empty string")
    if "@" in email_domain or re.search(r"\s", email_domain):
        raise ValueError("email_domain must not contain '@' or whitespace")

    try:
        names = list(latin_names) + list(other_names)
    except TypeError as exc:
        raise TypeError("Name collections must be iterable") from exc

    if not names:
        raise ValueError("At least one name must be provided")
    if any(not isinstance(name, str) or not name for name in names):
        raise ValueError("Names must be non-empty strings")

    def correct_encoding(name):
        """Correct common UTF-8 text decoded as Latin-1."""
        corrected = name

        for _ in range(3):
            if not any(marker in corrected for marker in ("Ã", "Â", "â", "ð", "�")):
                break

            try:
                candidate = corrected.encode("latin-1").decode("utf-8")
            except (UnicodeEncodeError, UnicodeDecodeError):
                break

            if candidate == corrected:
                break
            corrected = candidate

        return corrected

    def days_in_month(year, month):
        if month == 2:
            leap = year % 4 == 0 and (year % 100 != 0 or year % 400 == 0)
            return 29 if leap else 28
        return 30 if month in (4, 6, 9, 11) else 31

    rng = np.random.default_rng(rng_seed)

    selected_names = [
        correct_encoding(name)
        for name in rng.choice(names, size=100)
    ]

    years = rng.integers(start_year, end_year + 1, size=100)
    dates = []

    for year_value in years:
        year = int(year_value)
        month = int(rng.integers(1, 13))
        day = int(rng.integers(1, days_in_month(year, month) + 1))
        dates.append(f"{year:04d}-{month:02d}-{day:02d} 00:00:00")

    emails = [
        f"{name.lower()}{int(year)}@{email_domain}"
        for name, year in zip(selected_names, years)
    ]

    return pd.DataFrame({
        "ID": np.arange(1, 101),
        "Name": selected_names,
        "Date of Birth": dates,
        "Email": emails,
    })

