import nltk
from string import punctuation


def task_func(df):
    required_columns = {"Title", "Content"}

    if df.empty or not required_columns.issubset(df.columns):
        raise ValueError(
            "DataFrame must be non-empty and contain 'Title' and 'Content' columns."
        )

    title_pattern = r"\b(?:like|what)\b"
    matching_rows = df[
        df["Title"]
        .fillna("")
        .astype(str)
        .str.contains(title_pattern, case=False, regex=True, na=False)
    ]

    words = []

    for content in matching_rows["Content"].dropna():
        cleaned_content = str(content).translate(
            str.maketrans("", "", punctuation)
        )
        words.extend(re.findall(r"\b\w+\b", cleaned_content.lower()))

    return dict(nltk.FreqDist(words))

