import collections
from itertools import zip_longest
from random import choices


def task_func(l1, l2, K=10):
    if K < 0:
        raise ValueError("K must be non-negative")

    sentinel = object()
    combined = []

    for first, second in zip_longest(l1, l2, fillvalue=sentinel):
        if first is not sentinel:
            combined.append(first)
        if second is not sentinel:
            combined.append(second)

    return collections.Counter(choices(combined, k=K))

import numpy as np
from sklearn.decomposition import PCA
import matplotlib.pyplot as plt


def task_func(P, T, tensor_shape=(3, 3, 3)):
    if not isinstance(P, (np.ndarray, np.matrix)):
        raise TypeError("P must be a NumPy array or matrix.")
    if not isinstance(T, (np.ndarray, np.matrix)):
        raise TypeError("T must be a NumPy array or matrix.")

    try:
        tensor_shape = tuple(tensor_shape)
    except TypeError as exc:
        raise ValueError(
            "tensor_shape must contain three positive integers."
        ) from exc

    if (
        len(tensor_shape) != 3
        or any(
            isinstance(dim, bool)
            or not isinstance(dim, (int, np.integer))
            or dim <= 0
            for dim in tensor_shape
        )
    ):
        raise ValueError("tensor_shape must contain three positive integers.")

    P_array = np.asarray(P)
    T_array = np.asarray(T)

    if P_array.ndim != 2:
        raise ValueError("P must be two-dimensional.")

    if T_array.size != np.prod(tensor_shape):
        raise ValueError("T size does not match tensor_shape.")

    if P_array.shape[1] != tensor_shape[0]:
        raise ValueError(
            "The number of columns in P must match the first tensor dimension."
        )

    if P_array.shape[0] < 2 or tensor_shape[1] * tensor_shape[2] < 2:
        raise ValueError(
            "PCA requires at least two observations and two features."
        )

    tensor = T_array.reshape(tensor_shape)
    product = np.tensordot(P_array, tensor, axes=([1], [0]))
    data = product.reshape(P_array.shape[0], -1)

    pca_result = PCA(n_components=2).fit_transform(data)

    _, ax = plt.subplots()
    ax.scatter(pca_result[:, 0], pca_result[:, 1])
    ax.set_title("PCA Result Visualization")
    ax.set_xlabel("Principal Component 1")
    ax.set_ylabel("Principal Component 2")

    return pca_result, ax

import pandas as pd
from sklearn.linear_model import LinearRegression

DATA = {
    "Area_String": ["1,000", "2,000", "3,000", "4,000", "5,000"],
    "Price": [100, 200, 300, 400, 500],
}


def task_func(area_string, data=DATA):
    """Train a linear regression model and predict the price for an area."""
    if area_string is None:
        raise ValueError("area_string must contain a valid area")

    try:
        area = float(str(area_string).strip().replace(",", ""))
    except (TypeError, ValueError) as exc:
        raise ValueError("area_string must contain a numeric area") from exc

    if pd.isna(area) or area in (float("inf"), float("-inf")):
        raise ValueError("area_string must contain a valid area")

    frame = pd.DataFrame(data)

    if not {"Area_String", "Price"}.issubset(frame.columns):
        raise ValueError("data must contain Area_String and Price columns")

    frame["Area"] = pd.to_numeric(
        frame["Area_String"].astype(str).str.replace(",", "", regex=False),
        errors="coerce",
    )
    frame["Price"] = pd.to_numeric(frame["Price"], errors="coerce")
    frame = frame[
        frame["Area"].notna()
        & frame["Price"].notna()
        & frame["Area"].ne(float("inf"))
        & frame["Area"].ne(float("-inf"))
        & frame["Price"].ne(float("inf"))
        & frame["Price"].ne(float("-inf"))
    ]

    if len(frame) < 2:
        raise ValueError("data must contain at least two valid observations")

    model = LinearRegression()
    model.fit(frame[["Area"]], frame["Price"])

    return float(model.predict(pd.DataFrame({"Area": [area]}))[0])

from collections import defaultdict
import numpy as np
import matplotlib.pyplot as plt


def task_func(data):
    if not isinstance(data, list):
        raise TypeError("Input must be a list of dictionaries")

    if not data:
        raise ValueError("Input data must not be empty")

    if any(not isinstance(item, dict) for item in data):
        raise TypeError("Input must be a list of dictionaries")

    values_by_key = defaultdict(list)

    for item in data:
        for key, value in item.items():
            if isinstance(value, (bool, np.bool_)) or not isinstance(
                value, (int, float, np.integer, np.floating)
            ):
                raise TypeError("All dictionary values must be numeric")
            values_by_key[key].append(value)

    statistics = {}
    axes = []

    for key, values in values_by_key.items():
        mean = float(np.mean(values))
        standard_deviation = float(np.std(values))

        statistics[key] = {
            "mean": mean,
            "std": standard_deviation,
        }

        _, ax = plt.subplots()
        ax.bar(
            ["Mean", "Standard deviation"],
            [mean, standard_deviation],
        )
        ax.set_title(f"Statistics for {key}")
        ax.set_ylabel("Value")
        axes.append(ax)

    return statistics, axes

