import re
import os
import glob


def task_func(dir_path):
    if not os.path.isdir(dir_path):
        raise ValueError(f"Directory does not exist: {dir_path}")

    pattern = re.compile(r"\berror\b", re.IGNORECASE)
    result = {}

    for file_path in glob.glob(
        os.path.join(dir_path, "**", "*.txt"),
        recursive=True,
    ):
        if not os.path.isfile(file_path):
            continue

        with open(file_path, "r", encoding="utf-8") as file:
            content = file.read()

        relative_path = os.path.relpath(file_path, dir_path)
        result[relative_path] = len(pattern.findall(content))

    return result

import json
from glob import glob


def task_func(directory, string):
    def contains_string(value):
        if isinstance(value, dict):
            return any(
                contains_string(key) or contains_string(item)
                for key, item in value.items()
            )

        if isinstance(value, list):
            return any(contains_string(item) for item in value)

        return isinstance(value, str) and (
            value == "" if string == "" else string in value
        )

    json_files = glob(f"{directory}/**/*.json", recursive=True)
    matches = []

    for path in json_files:
        try:
            with open(path, "r", encoding="utf-8") as file:
                data = json.load(file)
        except (OSError, UnicodeDecodeError, json.JSONDecodeError):
            continue

        if contains_string(data):
            matches.append(path)

    return matches

