import matplotlib.pyplot as plt
from itertools import zip_longest

# Constants
COLORS = ['red', 'green', 'blue', 'yellow', 'purple']


def task_func(data, labels):
    """Plot data series with cycling colors and black for excess series."""
    _, ax = plt.subplots()

    series = list(data)
    labels = list(labels)

    for index, (values, label) in enumerate(
        zip_longest(series, labels, fillvalue=None)
    ):
        if values is None:
            continue

        if index >= len(COLORS) + len(labels):
            color = 'black'
        else:
            color = COLORS[index % len(COLORS)]

        if label is None:
            ax.plot(values, color=color)
        else:
            ax.plot(values, color=color, label=label)

    if labels:
        ax.legend()

    return ax

