import time
import numpy as np


def task_func(samples=10, delay=0.1):
    if (
        isinstance(samples, (bool, np.bool_))
        or not isinstance(samples, (int, np.integer))
        or samples <= 0
    ):
        raise ValueError("samples must be a positive integer")

    if delay < 0:
        raise ValueError("delay must be non-negative")

    delay_times = []

    for _ in range(samples):
        start = time.perf_counter()
        time.sleep(delay)
        delay_times.append(time.perf_counter() - start)

    return float(np.mean(delay_times)), float(np.std(delay_times))

import cv2
import numpy as np
import os


def task_func(img_path):
    if not os.path.exists(img_path):
        raise FileNotFoundError(img_path)

    original_image = cv2.imread(img_path, cv2.IMREAD_COLOR)
    if original_image is None:
        raise ValueError(f"Unable to read image: {img_path}")

    grayscale = cv2.cvtColor(original_image, cv2.COLOR_BGR2GRAY)

    _, binary = cv2.threshold(
        grayscale, 0, 255, cv2.THRESH_BINARY + cv2.THRESH_OTSU
    )
    contours, _ = cv2.findContours(
        binary, cv2.RETR_EXTERNAL, cv2.CHAIN_APPROX_SIMPLE
    )

    return original_image, list(contours)

