import numpy as np
import cv2
import os


def task_func(image_path='image.jpg', threshold=128):
    if not os.path.isfile(image_path):
        raise FileNotFoundError(f"Image file not found: {image_path}")

    if isinstance(threshold, (bool, np.bool_)) or not isinstance(
        threshold, (int, np.integer)
    ):
        raise ValueError("Threshold must be an integer from 0 to 255.")

    threshold = int(threshold)
    if not 0 <= threshold <= 255:
        raise ValueError("Threshold must be an integer from 0 to 255.")

    original_image = cv2.imread(image_path, cv2.IMREAD_GRAYSCALE)
    if original_image is None:
        raise ValueError(f"Unable to read image: {image_path}")

    binary_image = np.where(original_image >= threshold, 255, 0).astype(np.uint8)

    if not cv2.imwrite("binary_image.jpg", binary_image):
        raise IOError("Failed to save binary image.")

    return original_image, binary_image

import binascii
import numpy as np
import matplotlib.pyplot as plt
import pandas as pd


def task_func(hex_str):
    if not isinstance(hex_str, str):
        raise ValueError("hex_str must be a string")

    if hex_str == "":
        normalized = ""
    elif "\\" not in hex_str:
        normalized = hex_str
    elif hex_str.startswith("\\x"):
        parts = hex_str.split("\\x")[1:]

        if len(parts) == 1:
            normalized = parts[0]
        elif all(
            len(part) == 2
            and all(char in "0123456789abcdefABCDEF" for char in part)
            for part in parts
        ):
            normalized = "".join(parts)
        else:
            raise ValueError("Invalid hex string")
    else:
        raise ValueError("Invalid hex string")

    if len(normalized) % 2 != 0 or any(
        char not in "0123456789abcdefABCDEF" for char in normalized
    ):
        raise ValueError("Invalid hex string")

    try:
        raw_bytes = binascii.unhexlify(normalized)
    except (binascii.Error, ValueError, TypeError) as exc:
        raise ValueError("Invalid hex string") from exc

    byte_array = np.frombuffer(raw_bytes, dtype=np.uint8)
    byte_values, frequencies = np.unique(byte_array, return_counts=True)

    dataframe = pd.DataFrame(
        {
            "Byte Value": byte_values,
            "Frequency": frequencies,
        }
    )

    _, axes = plt.subplots()
    axes.bar(byte_values, frequencies)
    axes.set_xlabel("Byte Value")
    axes.set_ylabel("Frequency")

    return dataframe, axes

