import re
import pandas as pd


def task_func(df: pd.DataFrame, column_name: str, pattern: str) -> pd.DataFrame:
    result = df.copy()

    if pattern == "":
        return result

    regex = re.compile(pattern)

    def reorder_words(value):
        if not isinstance(value, str):
            return value

        words = value.split()
        matching_words = [word for word in words if regex.search(word)][::-1]

        matching_index = 0
        reordered = []

        for word in words:
            if regex.search(word):
                reordered.append(matching_words[matching_index])
                matching_index += 1
            else:
                reordered.append(word)

        return " ".join(reordered)

    result[column_name] = result[column_name].apply(reorder_words)
    return result

