import json
import os
import re


def task_func(
    file_path,
    attribute,
    INPUT_JSON={
        "type": "object",
        "properties": {
            "name": {"type": str},
            "age": {"type": int},
            "email": {"type": str},
        },
        "required": ["name", "age", "email"],
    },
    EMAIL_REGEX=r"^[a-z0-9]+[\._]?[a-z0-9]+[@]\w+[.]\w{2,3}$",
):
    if not isinstance(file_path, (str, bytes, os.PathLike)) or not os.path.isfile(
        file_path
    ):
        raise ValueError("The specified file does not exist.")

    try:
        with open(file_path, "r", encoding="utf-8") as file:
            data = json.load(file)
    except (OSError, UnicodeDecodeError, json.JSONDecodeError) as exc:
        raise ValueError("Unable to read or parse the JSON file.") from exc

    if INPUT_JSON.get("type") == "object" and not isinstance(data, dict):
        raise ValueError("The JSON root must be an object.")

    if not isinstance(data, dict):
        raise ValueError("The JSON root must be an object.")

    required = INPUT_JSON.get("required", [])
    missing = [field for field in required if field not in data]
    if missing:
        raise ValueError(f"Missing required attributes: {', '.join(missing)}")

    for field, schema in INPUT_JSON.get("properties", {}).items():
        if field not in data:
            continue

        expected_type = schema.get("type")
        value = data[field]

        if expected_type is int and isinstance(value, bool):
            raise ValueError(f"Attribute '{field}' has an invalid type.")

        try:
            valid_type = isinstance(value, expected_type)
        except TypeError as exc:
            raise ValueError(f"Invalid schema type for attribute '{field}'.") from exc

        if not valid_type:
            raise ValueError(f"Attribute '{field}' has an invalid type.")

    email = data.get("email")
    if not isinstance(email, str):
        raise ValueError("Invalid email format.")

    try:
        matches = re.fullmatch(EMAIL_REGEX, email)
    except re.error as exc:
        raise ValueError("Invalid email format.") from exc

    if matches is None:
        raise ValueError("Invalid email format.")

    if attribute not in data:
        raise ValueError(f"Attribute '{attribute}' is missing.")

    return data[attribute]

