        data = [row + [None] * (width - len(row)) for row in data]
        columns = headers + list(range(len(headers), width))
        return pd.DataFrame(data, columns=columns)

    return pd.DataFrame(data)

import shutil
from pathlib import Path
from typing import List


def task_func(source_dir: str, target_dir: str, extensions: List[str]) -> int:
    source = Path(source_dir)
    target = Path(target_dir)

    if not source.is_dir() or not target.is_dir():
        raise ValueError("source_dir or target_dir does not exist")

    if source.resolve() == target.resolve():
        return 0

    normalized_extensions = {
        extension if extension.startswith(".") else f".{extension}"
        for extension in extensions
    }

    moved_count = 0
    for path in source.iterdir():
        if path.is_file() and path.suffix in normalized_extensions:
            shutil.move(str(path), str(target / path.name))
            moved_count += 1

    return moved_count

