import math
from collections.abc import Mapping
from geopy.exc import GeocoderServiceError, GeocoderTimedOut


def task_func(dic):
    if not isinstance(dic, Mapping):
        raise TypeError("dic must be a mapping of labels to locations")

    geolocator = Photon(user_agent="geoapiExercises")
    locations = []

    for label, value in dic.items():
        coordinates = None

        if isinstance(value, str):
            if not value.strip():
                continue

            try:
                result = geolocator.geocode(value)
            except (GeocoderTimedOut, GeocoderServiceError):
                continue

            if result is not None:
                coordinates = (result.latitude, result.longitude)
        elif not isinstance(value, Mapping):
            try:
                pair = list(value)
            except (TypeError, ValueError):
                continue

            if len(pair) == 2:
                coordinates = pair

        if coordinates is None:
            continue

        try:
            latitude = float(coordinates[0])
            longitude = float(coordinates[1])
        except (TypeError, ValueError):
            continue

        if (
            not math.isfinite(latitude)
            or not math.isfinite(longitude)
            or not -90 <= latitude <= 90
            or not -180 <= longitude <= 180
        ):
            continue

        locations.append((label, latitude, longitude))

    center = (
        (locations[0][1], locations[0][2])
        if locations
        else (0, 0)
    )

    result_map = folium.Map(location=center, zoom_start=2)

    for label, latitude, longitude in locations:
        folium.Marker(
            location=(latitude, longitude),
            popup=str(label),
            tooltip=str(label),
        ).add_to(result_map)

    return result_map

