import cgi
import http.server
import smtplib
from email.mime.text import MIMEText
import json


def task_func(smtp_server, smtp_port, smtp_username, smtp_password):
    class EmailRequestHandler(http.server.BaseHTTPRequestHandler):
        def _send_response(self, status, body):
            if isinstance(body, str):
                body = body.encode("utf-8")

            self.send_response(status)
            self.send_header("Content-Type", "application/json")
            self.send_header("Content-Length", str(len(body)))
            self.end_headers()
            self.wfile.write(body)

        def do_POST(self):
            try:
                content_length = int(self.headers.get("Content-Length", "0"))
                body = self.rfile.read(content_length)
                data = json.loads(body.decode("utf-8"))

                if not isinstance(data, dict):
                    raise ValueError("Email data must be a JSON object")

                for key in ("subject", "message", "to"):
                    if key not in data:
                        raise ValueError(f"Missing required key: {key}")

                recipients = data["to"]
                if isinstance(recipients, list):
                    recipient_list = [str(recipient) for recipient in recipients]
                else:
                    recipient_list = [str(recipients)]

                message = MIMEText(str(data["message"]), "plain", "utf-8")
                message["Subject"] = str(data["subject"])
                message["From"] = str(smtp_username)
                message["To"] = ", ".join(recipient_list)

                with smtplib.SMTP(smtp_server, smtp_port) as server:
                    server.login(smtp_username, smtp_password)
                    server.sendmail(
                        smtp_username,
                        recipient_list,
                        message.as_string(),
                    )

                self._send_response(
                    200,
                    json.dumps({"status": "Email sent"}),
                )
            except (json.JSONDecodeError, UnicodeDecodeError, ValueError):
                self._send_response(
                    400,
                    json.dumps({"error": "Bad Request"}),
                )
            except smtplib.SMTPAuthenticationError:
                self._send_response(
                    535,
                    json.dumps({"error": "Authentication Failed"}),
                )
            except Exception:
                self._send_response(
                    500,
                    json.dumps({"error": "Internal Server Error"}),
                )

    return EmailRequestHandler

