import shutil

# Constants
DOWNLOAD_DIR = Path("downloads")
ZIP_DIR = Path("unzipped_files")


def task_func(url, filename):
    try:
        DOWNLOAD_DIR.mkdir(parents=True, exist_ok=True)
        ZIP_DIR.mkdir(parents=True, exist_ok=True)

        filename_path = Path(filename)
        if filename_path.is_absolute() or ".." in filename_path.parts:
            raise ValueError("filename must refer to a file inside downloads")

        zip_path = DOWNLOAD_DIR / filename_path
        download_root = DOWNLOAD_DIR.resolve()

        if zip_path.resolve().parent != download_root:
            raise ValueError("filename must refer to a file directly inside downloads")

        response = requests.get(url, timeout=30)
        response.raise_for_status()
        zip_path.write_bytes(response.content)

    except requests.RequestException as exc:
        return (f"Error downloading file: {exc}", [])
    except (OSError, TypeError, ValueError) as exc:
        return (f"Error handling file: {exc}", [])

    try:
        output_root = ZIP_DIR.resolve()
        extracted_files = []

        with zipfile.ZipFile(zip_path, "r") as archive:
            for member in archive.infolist():
                member_path = Path(member.filename)

                if member_path.is_absolute() or ".." in member_path.parts:
                    raise ValueError("ZIP archive contains an unsafe path")

                if member.is_dir():
                    target = (ZIP_DIR / member_path).resolve()
                else:
                    target = (ZIP_DIR / member_path).resolve()

                if target != output_root and output_root not in target.parents:
                    raise ValueError("ZIP archive contains an unsafe path")

                current = ZIP_DIR
                for part in member_path.parts:
                    if part in ("", "."):
                        continue
                    current /= part
                    if current.is_symlink():
                        raise ValueError("ZIP archive would overwrite a symbolic link")

                if member.is_dir():
                    target.mkdir(parents=True, exist_ok=True)
                    continue

                target.parent.mkdir(parents=True, exist_ok=True)
                with archive.open(member) as source, target.open("wb") as destination:
                    shutil.copyfileobj(source, destination)

                extracted_files.append(target.relative_to(output_root).as_posix())

        return ("File downloaded and extracted successfully.", extracted_files)

    except (
        OSError,
        ValueError,
        NotImplementedError,
        zipfile.BadZipFile,
        zipfile.LargeZipFile,
    ) as exc:
        return (f"Error extracting file: {exc}", [])

