import collections
import random
import json

# Constants
PREFICES = ['EMP$$', 'MAN$$', 'DEV$$', 'HR$$']
LEVELS = ['Junior', 'Mid', 'Senior']


def task_func(department_data):
    """Return a JSON object mapping department codes to employee levels."""
    if not isinstance(department_data, collections.abc.Mapping):
        raise TypeError("department_data must be a mapping")

    result = {}

    for department, count in department_data.items():
        if department not in PREFICES:
            continue

        if isinstance(count, bool) or not isinstance(count, int):
            raise TypeError(f"Employee count for {department} must be an integer")
        if count < 0:
            raise ValueError(f"Employee count for {department} cannot be negative")

        result[department] = [random.choice(LEVELS) for _ in range(count)]

    return json.dumps(result)

