import pandas as pd
from sklearn.linear_model import LinearRegression
import matplotlib.pyplot as plt


def task_func(df):
    if not isinstance(df, pd.DataFrame):
        raise ValueError("df must be a pandas DataFrame")

    if not {"date", "value"}.issubset(df.columns):
        raise ValueError("DataFrame must contain 'date' and 'value' columns")

    if df.empty:
        raise ValueError("DataFrame must not be empty")

    if not pd.api.types.is_datetime64_any_dtype(df["date"]):
        raise ValueError("'date' column must be in datetime format")

    if df["date"].isna().any():
        raise ValueError("'date' column must not contain missing values")

    if not pd.api.types.is_numeric_dtype(df["value"]):
        raise ValueError("'value' column must be numeric")

    try:
        values = df["value"].to_numpy(dtype="float64")
    except (TypeError, ValueError):
        raise ValueError("'value' column must contain valid numeric values")

    if not pd.Series(values).map(pd.notna).all() or not (
        (values != float("inf")) & (values != -float("inf"))
    ).all():
        raise ValueError("'value' column must contain finite values")

    date_ordinals = df["date"].map(lambda date: date.toordinal()).to_numpy().reshape(-1, 1)

    model = LinearRegression()
    model.fit(date_ordinals, values)
    predictions = model.predict(date_ordinals)

    _, ax = plt.subplots()
    ax.plot(date_ordinals.ravel(), values, label="Original values")
    ax.plot(date_ordinals.ravel(), predictions, label="Predicted values")
    ax.set_title("Value vs Date (Linear Regression Prediction)")
    ax.set_xlabel("Date (ordinal)")
    ax.set_ylabel("Value")
    ax.legend()

    return model, predictions, ax

