import matplotlib.pyplot as plt


def task_func(df):
    if df.empty:
        return 0, 0

    list_column = next(
        (
            column
            for column in df.columns
            if df[column].map(
                lambda value: isinstance(value, (list, tuple))
            ).any()
        ),
        None,
    )

    if list_column is None:
        raise ValueError("DataFrame must contain a column with lists of numbers.")

    features = pd.DataFrame(df[list_column].tolist(), index=df.index)

    if features.empty or features.shape[1] == 0:
