import matplotlib.pyplot as plt
import pandas as pd


def task_func(df, tuples, n_plots):
    if not isinstance(df, pd.DataFrame):
        raise TypeError("df must be a pandas DataFrame")

    if not isinstance(n_plots, numbers.Integral):
        raise TypeError("n_plots must be an integer")
    if n_plots < 0:
        raise ValueError("n_plots must be non-negative")

    columns = list(df.columns)
    rows_to_remove = []

    for values in tuples:
        values = tuple(values)
        if len(values) != len(columns):
            raise ValueError(
                "Each tuple must contain one value for every DataFrame column"
            )
        rows_to_remove.append(values)

    if rows_to_remove:
        remove_mask = pd.Series(False, index=df.index)

        for values in rows_to_remove:
            row_mask = pd.Series(True, index=df.index)

            for column, value in zip(columns, values):
                if pd.isna(value):
                    comparison = df[column].isna()
                else:
                    comparison = df[column].eq(value).fillna(False)

                row_mask &= comparison

            remove_mask |= row_mask

        filtered_df = df.loc[~remove_mask].copy()
    else:
        filtered_df = df.copy()

    column_pairs = list(combinations(columns, 2))
    selected_pairs = sample(
        column_pairs,
        min(int(n_plots), len(column_pairs)),
    )

    plots = []
    for column_pair in selected_pairs:
        x_column, y_column = column_pair
        _, ax = plt.subplots()
        ax.scatter(filtered_df[x_column], filtered_df[y_column])
        ax.set_xlabel(x_column)
        ax.set_ylabel(y_column)
        plots.append((column_pair, ax))

    return filtered_df, plots

