import pandas as pd
from sklearn.preprocessing import LabelEncoder


def task_func(df, dct, columns=None):
    if not isinstance(df, pd.DataFrame):
        raise ValueError("df must be a pandas DataFrame")

    result = df.copy()
    result = result.replace(dct)

    if columns is None:
        categorical_columns = result.select_dtypes(
            include=["object", "category"]
        ).columns.tolist()
    else:
        categorical_columns = list(columns)

    for column in categorical_columns:
        result[column] = LabelEncoder().fit_transform(result[column])

    numeric_columns = result.select_dtypes(include="number").columns
    numeric_columns = numeric_columns.difference(categorical_columns)

    for column in numeric_columns:
        mean = result[column].mean()
        std = result[column].std()

        if pd.isna(std) or std == 0:
            result[column] = 0
        else:
            result[column] = (result[column] - mean) / std

    return result

import subprocess
import shutil
import os
import sys


def task_func(script_path: str, temp_dir: str) -> str:
    try:
        source = os.path.abspath(script_path)
        destination_dir = os.path.abspath(temp_dir)

        if not os.path.isfile(source):
            return "Script execution failed!"

        os.makedirs(destination_dir, exist_ok=True)

        destination = os.path.join(
            destination_dir,
            os.path.basename(source),
        )

        if not os.path.exists(destination) or not os.path.samefile(source, destination):
            shutil.copy2(source, destination)

        result = subprocess.run(
            [sys.executable, destination],
            cwd=destination_dir,
            check=False,
        )

        return (
            "Script executed successfully!"
            if result.returncode == 0
            else "Script execution failed!"
        )
    except (OSError, shutil.Error, subprocess.SubprocessError):
        return "Script execution failed!"

import subprocess
import psutil
import time


def task_func(process_name: str) -> str:
    matching_processes = []

    for process in psutil.process_iter(["name"]):
        try:
            if process.info.get("name") == process_name:
                matching_processes.append(process)
        except (psutil.NoSuchProcess, psutil.AccessDenied):
            continue

    if not matching_processes:
        subprocess.Popen([process_name])
        return f"Process not found. Starting {process_name}."

    for process in matching_processes:
        try:
            process.terminate()
        except (psutil.NoSuchProcess, psutil.AccessDenied):
            continue

    for process in matching_processes:
        try:
            process.wait(timeout=3)
        except (psutil.NoSuchProcess, psutil.TimeoutExpired, psutil.AccessDenied):
            continue

    subprocess.Popen([process_name])
    return f"Process found. Restarting {process_name}."

