from itertools import cycle


def task_func(df, groups=['A', 'B', 'C', 'D', 'E']):
    if not isinstance(df, pd.DataFrame):
        raise ValueError("df must be a pandas DataFrame")

    required_columns = {"Date", "Value", "Group"}
    if not required_columns.issubset(df.columns):
        raise ValueError("df must contain Date, Value, and Group columns")

    try:
        dates = pd.to_datetime(df["Date"], errors="raise")
        if dates.isna().any():
            raise ValueError("Date column contains missing values")
        ordinals = dates.map(lambda date: date.toordinal())
    except ValueError:
        raise
    except Exception as exc:
        raise ValueError("Date column contains invalid values") from exc

    _, ax = plt.subplots()
    colors = cycle(plt.rcParams["axes.prop_cycle"].by_key()["color"])

    for group in groups:
        mask = df["Group"] == group
        if not mask.any():
            continue

        ax.scatter(
            ordinals[mask],
            df.loc[mask, "Value"],
            color=next(colors),
            label=group,
        )

    ax.set_title("Scatterplot of Values for Each Group Over Time")
    ax.set_xlabel("Date (ordinal)")
    ax.set_ylabel("Value")

    if ax.collections:
        ax.legend()

    return ax

