import json
from collections import Counter
import re


def task_func(json_dir_path, word_count):
    if isinstance(word_count, bool) or not isinstance(word_count, int):
        return []
    if word_count <= 0:
        return []
    if not isinstance(json_dir_path, (str, os.PathLike)):
        return []

    try:
        if not os.path.isdir(json_dir_path):
            return []
        filenames = os.listdir(json_dir_path)
    except (OSError, TypeError):
        return []

    def extract_strings(value):
        if isinstance(value, str):
            return [value]
        if isinstance(value, dict):
            result = []
            for item in value.values():
                result.extend(extract_strings(item))
            return result
        if isinstance(value, list):
            result = []
            for item in value:
                result.extend(extract_strings(item))
            return result
        return []

    word_counter = Counter()

    for filename in filenames:
        if not filename.lower().endswith(".json"):
            continue

        file_path = os.path.join(json_dir_path, filename)

        try:
            with open(file_path, "r", encoding="utf-8") as file:
                data = json.load(file)
        except (OSError, UnicodeDecodeError, json.JSONDecodeError):
            continue

        text = " ".join(extract_strings(data))
        words = re.findall(r"\b\w+\b", text.lower(), flags=re.UNICODE)
        word_counter.update(words)

    return word_counter.most_common(word_count)

