import pandas as pd
from scipy.stats import pearsonr


def task_func(data):
    if len(data) < 2:
        return float("nan")

    scores = pd.to_numeric(data["score"], errors="raise").astype(float)
    grades = data["grade"]

    if isinstance(grades.dtype, pd.CategoricalDtype) and grades.cat.ordered:
        encoded_grades = pd.Series(grades.cat.codes, index=grades.index, dtype=float)
        encoded_grades = encoded_grades.replace(-1, float("nan"))
    else:
        unique_grades = grades.dropna().unique().tolist()
        try:
            ordered_grades = sorted(unique_grades)
        except TypeError:
            ordered_grades = sorted(unique_grades, key=repr)

        grade_mapping = {
            grade: rank for rank, grade in enumerate(ordered_grades)
        }
        encoded_grades = grades.map(grade_mapping).astype(float)

    valid = scores.notna() & encoded_grades.notna()
    scores = scores[valid]
    encoded_grades = encoded_grades[valid]

    if len(scores) < 2:
        return float("nan")

    return float(pearsonr(scores, encoded_grades).statistic)

