def task_func(repo_url: str) -> dict:
    """Fetch and return information about a GitHub repository."""
    response = None
    open_issues_threshold = 100

    try:
        response = requests.get(repo_url)
        response.raise_for_status()

        try:
            repository_info = response.json()
        except ValueError as exc:
            raise requests.exceptions.RequestException(
                "GitHub API returned invalid JSON."
            ) from exc

        if not isinstance(repository_info, dict):
            raise requests.exceptions.RequestException(
                "GitHub API returned an invalid response format."
            )

        open_issues = repository_info.get("open_issues_count", 0)
        if type(open_issues) is int and open_issues > open_issues_threshold:
            logging.warning(
                "Repository has a large number of open issues: %s",
                open_issues,
            )

        return repository_info

    except requests.exceptions.HTTPError:
        if (
            response is not None
            and response.status_code == 403
            and response.headers.get("X-RateLimit-Remaining") == "0"
        ):
            logging.error("GitHub API rate limit exceeded.")
        raise

    except requests.exceptions.RequestException:
        logging.error("Failed to fetch GitHub repository information.")
        raise

