def task_func(df: pd.DataFrame, tuples: list, n_plots: int) -> (pd.DataFrame, list):
    missing_columns = [column for column in COLUMNS if column not in df.columns]
    if missing_columns:
        raise ValueError(f"DataFrame is missing required columns: {missing_columns}")

    if n_plots < 0:
        raise ValueError("n_plots must be non-negative")

    remove_mask = pd.Series(False, index=df.index)

    for values in tuples:
        if len(values) != len(COLUMNS):
            raise ValueError(
                f"Each tuple must contain exactly {len(COLUMNS)} values"
            )

        row_mask = pd.Series(True, index=df.index)

        for column, value in zip(COLUMNS, values):
            if pd.isna(value):
                row_mask &= df[column].isna()
            else:
                row_mask &= df[column].eq(value).fillna(False)

        remove_mask |= row_mask

    filtered_df = df.loc[~remove_mask].copy()

    if filtered_df.empty:
        return filtered_df, []

    plots = []
    for _ in range(n_plots):
        x_column, y_column = sample(COLUMNS, 2)
        plots.append(
            sns.jointplot(
                data=filtered_df,
                x=x_column,
                y=y_column,
            )
        )

    return filtered_df, plots

