import time
import threading


def task_func(file_list):
    files = list(file_list)
    exit_codes = [-1] * len(files)
    processes = []

    for index, file_path in enumerate(files):
        try:
            process = subprocess.Popen([file_path])
        except (OSError, ValueError):
            continue
        processes.append((index, process))

    def wait_for_process(index, process):
        try:
            exit_codes[index] = process.wait()
        except OSError:
            exit_codes[index] = -1

    threads = [
        threading.Thread(target=wait_for_process, args=(index, process))
        for index, process in processes
    ]

    for thread in threads:
        thread.start()

    for thread in threads:
        thread.join()

    return exit_codes

import sqlite3
import pandas as pd
import csv
from io import StringIO

# Constants
DATABASE_NAME = 'test.db'
TABLE_NAME = 'test_table'


def task_func(csv_input):
    if isinstance(csv_input, StringIO):
        file_obj = csv_input
        close_file = False
    else:
        file_obj = open(csv_input, 'r', encoding='utf-8', newline='')
        close_file = True

    try:
        rows = list(csv.reader(file_obj))
    finally:
        if close_file:
            file_obj.close()

    if not rows:
        raise ValueError("CSV input is empty")

    headers = rows[0]

    if not headers or any(not header.strip() for header in headers):
        raise ValueError("CSV headers must not be empty")

    if len(set(headers)) != len(headers):
        raise ValueError("CSV headers must be unique")

    for row_number, row in enumerate(rows[1:], start=2):
        if len(row) != len(headers):
            raise ValueError(
                f"Row {row_number} has {len(row)} fields; "
                f"expected {len(headers)}"
            )

    def quote_identifier(identifier):
        return '"' + identifier.replace('"', '""') + '"'

    table_name = quote_identifier(TABLE_NAME)
    columns = ", ".join(quote_identifier(header) for header in headers)
    placeholders = ", ".join("?" for _ in headers)

    connection = sqlite3.connect(DATABASE_NAME)

    try:
        with connection:
            connection.execute(f"DROP TABLE IF EXISTS {table_name}")
            connection.execute(
                f"CREATE TABLE {table_name} ({columns})"
            )

            if rows[1:]:
                connection.executemany(
                    f"INSERT INTO {table_name} ({columns}) "
                    f"VALUES ({placeholders})",
                    rows[1:],
                )

            return pd.read_sql_query(
                f"SELECT * FROM {table_name}",
                connection,
            )
    finally:
        connection.close()

