# Constants
PREFIXES = ["is_", "has_", "can_", "should_"]


def task_func(directory):
    if not os.path.isdir(directory):
        raise NotADirectoryError(f"Not a directory: {directory}")

    counts = {prefix: 0 for prefix in PREFIXES}

    def traverse(value):
        if isinstance(value, dict):
            for key, nested_value in value.items():
                if isinstance(key, str):
                    for prefix in PREFIXES:
                        if key.startswith(prefix):
                            counts[prefix] += 1
                traverse(nested_value)
        elif isinstance(value, list):
            for item in value:
                traverse(item)

    with os.scandir(directory) as entries:
        for entry in entries:
            if not entry.is_file() or not entry.name.lower().endswith(".json"):
                continue

            try:
                with open(entry.path, "r", encoding="utf-8") as file:
                    data = json.load(file)
            except (OSError, UnicodeDecodeError, json.JSONDecodeError):
                continue

            traverse(data)

    return counts

from datetime import datetime
import pandas as pd
# For Python versions lower than 3.9, use 'pytz' instead of 'zoneinfo'
try:
    from zoneinfo import ZoneInfo
except ImportError:
    from pytz import timezone as ZoneInfo

TIME_FORMAT = "%d/%m/%y %H:%M:%S.%f"


def task_func(time_strings, target_tz):
    original_times = list(time_strings)
    target_timezone = ZoneInfo(target_tz)
    utc_timezone = ZoneInfo("UTC")

    converted_times = []

    for time_string in original_times:
        utc_time = datetime.strptime(time_string, TIME_FORMAT).replace(
            tzinfo=utc_timezone
        )
        converted_times.append(
            utc_time.astimezone(target_timezone).strftime(TIME_FORMAT)
        )

    return pd.DataFrame(
        {
            "Original Time": original_times,
            "Converted Time": converted_times,
        }
    )

