import json
from datetime import datetime
import numpy as np
from decimal import Decimal


def task_func(my_obj):
    class CustomJSONEncoder(json.JSONEncoder):
        def default(self, obj):
            if isinstance(obj, datetime):
                return obj.isoformat()
            if isinstance(obj, np.ndarray):
                return obj.tolist()
            if isinstance(obj, Decimal):
                return float(obj)
            if isinstance(obj, (np.integer, np.floating, np.bool_)):
                return obj.item()
            return super().default(obj)

    return json.dumps(my_obj, cls=CustomJSONEncoder)

from itertools import groupby
from operator import itemgetter
# Constants
KEY_FUNC = itemgetter(0)
def task_func(my_dict):
    if any(key == "" for key in my_dict):
        raise ValueError("Dictionary keys must be non-empty strings.")

    sorted_items = sorted(
        my_dict.items(),
        key=lambda item: KEY_FUNC(item)[0],
    )

    aggregated_dict = {}

    for first_character, group in groupby(
        sorted_items,
        key=lambda item: KEY_FUNC(item)[0],
    ):
        aggregated_dict[first_character] = sum(
            value for _, value in group
        )

    return aggregated_dict

import numpy as np
from sklearn.preprocessing import StandardScaler
from sklearn.metrics import mean_squared_error


def task_func(num_samples=1000, k=5, d=2, random_seed=None):
    if not isinstance(num_samples, (int, np.integer)) or num_samples <= 0:
        raise ValueError("num_samples must be a positive integer")

    rng = np.random.default_rng(random_seed)
    original = rng.normal(0, 1, num_samples)

    standardized = StandardScaler().fit_transform(
        original.reshape(-1, 1)
    ).ravel()

    transformed = k * standardized + d

    return float(mean_squared_error(original, transformed))

import pandas as pd
import os


def task_func(original_file_location="test.xlsx", new_file_location="new_test.xlsx", sheet_name="Sheet1"):
    if not os.path.isfile(original_file_location):
        raise FileNotFoundError(original_file_location)

    try:
        data = pd.read_excel(original_file_location, sheet_name=sheet_name)
    except ValueError as exc:
        raise ValueError(
            f"Sheet '{sheet_name}' does not exist in the workbook."
        ) from exc

    with pd.ExcelWriter(new_file_location, engine="openpyxl") as writer:
        data.to_excel(writer, sheet_name=sheet_name, index=False)

    return pd.read_excel(new_file_location, sheet_name=sheet_name)

